module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire winc,
    input wire wrstn,
    input wire rinc,
    input wire rrstn,
    input wire [WIDTH-1:0] wdata,
    output reg wfull,
    output reg rempty,
    output wire [WIDTH-1:0] rdata
);
    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH;


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin),
        .rdata(rdata)
    );


    reg [PTR_WIDTH-1:0] waddr_bin, wptr, rptr_sync;
    reg [PTR_WIDTH-1:0] wptr_buff, wptr_sync;


    reg [PTR_WIDTH-1:0] raddr_bin, rptr, wptr_sync;
    reg [PTR_WIDTH-1:0] rptr_buff, rptr_sync;


    always @* begin
        wptr = (waddr_bin >> 1) ^ waddr_bin;
        rptr = (raddr_bin >> 1) ^ raddr_bin;
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_buff <= 0;
            rptr_sync <= 0;
        end else begin
            rptr_buff <= rptr;
            rptr_sync <= rptr_buff;
        end
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_buff <= 0;
            wptr_sync <= 0;
        end else begin
            wptr_buff <= wptr;
            wptr_sync <= wptr_buff;
        end
    end


    wire full_cond = (wptr[3] != rptr_sync[3]) && (wptr[2] != rptr_sync[2]) && (wptr[1:0] == rptr_sync[1:0]);
    wire empty_cond = (rptr == rptr_sync);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) wfull <= 0;
        else wfull <= full_cond;
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) rempty <= 0;
        else rempty <= empty_cond;
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) waddr_bin <= 0;
        else if (winc && !wfull) waddr_bin <= waddr_bin + 1;
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) raddr_bin <= 0;
        else if (rinc && !rempty) raddr_bin <= raddr_bin + 1;
    end
endmodule

