                areg <= ain;
                breg <= bin;
            end


            if (i > 0 && i < 17) begin
                if (areg[i-1]) begin
                    yout_r <= yout_r + (breg << (i-1));
                end
            end


            if (i == 16) begin
                done_r <= 1'b1;
            end else if (i == 17) begin
                done_r <= 1'b0;
            end
        end
    end

    assign yout = yout_r;
    assign done = done_r;

