module fixed_point_adder #(parameter Q=4, N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire a_sign, b_sign;
    wire [N-1:0] mag_a, mag_b;
    wire [N:0] sum_mag;
    wire [N-1:0] sum_mag_truncated;
    wire sum_sign;
    wire [N-1:0] sub_mag;
    wire sub_sign;
    localparam MAX_MAG = (1 << (N-1)) - 1;

    assign a_sign = a[N-1];
    assign b_sign = b[N-1];

    assign mag_a = a_sign ? (~a + 1) : a;
    assign mag_b = b_sign ? (~b + 1) : b;

    always @* begin
        if (a_sign == b_sign) begin
            sum_mag = mag_a + mag_b;
            sum_sign = a_sign;
            if (sum_mag > MAX_MAG) begin
                sum_mag_truncated = {1'b0, {(N-1){1'b1}}};
            end else begin
                sum_mag_truncated = sum_mag[N-1:0];
            end
            res = {sum_sign, sum_mag_truncated[N-2:0]};
        end else begin
            if (mag_a > mag_b) begin
                sub_mag = mag_a - mag_b;
                sub_sign = a_sign;
            end else begin
                sub_mag = mag_b - mag_a;
                sub_sign = b_sign;
            end
            res = {sub_sign, sub_mag[N-2:0]};
        end
    end

    always @* begin
        c = res;
    end
endmodule

