module fixed_point_subtractor #(parameter Q=2, N=4) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire [N-1:0] abs_a, abs_b, sum;
    wire res_sign;

    always @* begin
        if (a[N-1] == b[N-1]) begin
            res = a - b;
            res[N-1] = a[N-1];

        end else begin
            abs_a = a[N-1] ? (~a + 1) : a;
            abs_b = b[N-1] ? (~b + 1) : b;
            sum = abs_a + abs_b;

            if (a[N-1] == 0) begin 
                res_sign = (abs_a > abs_b) ? 1'b0 : 1'b1;
            end else begin 
                res_sign = (abs_a > abs_b) ? 1'b1 : 1'b0;
            end
            res = {res_sign, sum[N-2:0]};
        end


        if (res[N-2:0] == 0)
            res[N-1] = 1'b0;
    end

    assign c = res;
endmodule

