module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output wire EMPTY,
    output wire FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];

integer i;

assign EMPTY = (SP == 3'd4);

assign FULL = (SP == 3'd0);


always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'd4;


        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 4'b0;
    end
    else if (EN) begin
        if (~RW && ~FULL) begin 
            stack_mem[SP-1] <= dataIn;

            SP <= SP - 1;

        end
        else if (RW && ~EMPTY) begin 
            dataOut <= stack_mem[SP];

            stack_mem[SP] <= 4'b0;

            SP <= SP + 1;

        end
    end
end

endmodule

