module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry, overflow,
    output negative,
    output flag
);
    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] res;
    reg flag_reg;
    wire [32:0] sum_33, sub_33;
    wire [4:0] shift_amount;
    reg [31:0] shifted;

    assign sum_33 = {1'b0, a} + {1'b0, b};
    assign sub_33 = {1'b0, a} - {1'b0, b};

    always @(*) begin
        case (aluc)
            ADD: begin
                res = sum_33[31:0];
                carry = sum_33[32];
                overflow = (a[31] == b[31]) && (res[31] != a[31]);
            end
            ADDU: begin
                res = a + b;
                carry = 0;
                overflow = 0;
            end
            SUB: begin
                res = sub_33[31:0];
                carry = sub_33[32];
                overflow = (a[31] != b[31]) && (res[31] != a[31]);
            end
            SUBU: begin
                res = a - b;
                carry = 0;
                overflow = 0;
            end
            AND: begin
                res = a & b;
                carry = 0;
                overflow = 0;
            end
            OR: begin
                res = a | b;
                carry = 0;
                overflow = 0;
            end
            XOR: begin
                res = a ^ b;
                carry = 0;
                overflow = 0;
            end
            NOR: begin
                res = ~(a | b);
                carry = 0;
                overflow = 0;
            end
            SLT: begin
                res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                carry = 0;
                overflow = 0;
            end
            SLTU: begin
                res = (a < b) ? 32'd1 : 32'd0;
                carry = 0;
                overflow = 0;
            end
            SLL: begin
                shift_amount = b[4:0];
                res = a << shift_amount;
                carry = 0;
                overflow = 0;
            end
            SRL: begin
                shift_amount = b[4:0];
                res = a >> shift_amount;
                carry = 0;
                overflow = 0;
            end
            SRA: begin
                shift_amount = b[4:0];
                res = $signed(a) >>> shift_amount;
                carry = 0;
                overflow = 0;
            end
            SLLV: begin
                shift_amount = a[4:0];
                res = b << shift_amount;
                carry = 0;
                overflow = 0;
            end
            SRLV: begin
                shift_amount = a[4:0];
                res = b >> shift_amount;
                carry = 0;
                overflow = 0;
            end
            SRAV: begin
                shift_amount = a[4:0];
                res = $signed(b) >>> shift_amount;
                carry = 0;
                overflow = 0;
            end
            LUI: begin
                res = {a[31:16], 16'b0};
                carry = 0;
                overflow = 0;
            end
            default: begin
                res = 32'bz;
                carry = 0;
                overflow = 0;
            end
        endcase
    end

    always @(*) begin
        zero = (res == 32'd0);
        negative = res[31];
        flag_reg = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;
    end

    assign r = res;
    assign flag = flag_reg;

endmodule

