module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg [7:0] temp_dividend_abs;
    reg [7:0] temp_divisor_abs;
    reg sign_dividend, sign_divisor;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg signed [8:0] NEG_DIVISOR;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            result <= 0;
            quotient <= 0;
            remainder <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            temp_dividend_abs <= 0;
            temp_divisor_abs <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
        end else begin
            if (res_valid) begin
                if (!opn_valid)
                    res_valid <= 0;
            end else begin
                if (opn_valid && !res_valid) begin

                    if (sign) begin
                        sign_dividend <= dividend[7];
                        sign_divisor <= divisor[7];
                        temp_dividend_abs <= dividend[7] ? (~dividend + 1) : dividend;
                        temp_divisor_abs <= divisor[7] ? (~divisor + 1) : divisor;
                    end else begin
                        sign_dividend <= 0;
                        sign_divisor <= 0;
                        temp_dividend_abs <= dividend;
                        temp_divisor_abs <= divisor;
                    end


                    SR <= {7'b0, (temp_dividend_abs << 1)};
                    NEG_DIVISOR <= -{1'b0, temp_divisor_abs};


                    cnt <= 1;
                    start_cnt <= 1;
                    res_valid <= 0;
                end else if (start_cnt) begin
                    if (cnt == 8) begin

                        start_cnt <= 0;
                        cnt <= 0;

                        if (sign) begin

                            quotient <= (sign_dividend ^ sign_divisor) ? (~quotient + 1) : quotient;
                            remainder <= sign_dividend ? (~remainder + 1) : remainder;
                        end

                        result <= {remainder, quotient};
                        res_valid <= 1;
                    end else begin

                        wire [8:0] temp_remainder = SR[8:0] - NEG_DIVISOR;
                        wire borrow = temp_remainder[8];


                        if (!borrow) begin
                            remainder <= temp_remainder[7:0];
                            quotient <= {quotient[6:0], 1'b1};
                        end else begin
                            remainder <= SR[8:0];
                            quotient <= {quotient[6:0], 1'b0};
                        end

                        SR <= {remainder, quotient} << 1;

                        cnt <= cnt + 1;
                    end
                end
            end
        end
    end
endmodule

