module fixed_point_adder #(parameter Q=2, N=8) (
    input wire [N-1:0] a, b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire [N-1:0] a_abs = a[N-1] ? (-a) : a;
    wire [N-1:0] b_abs = b[N-1] ? (-b) : b;
    wire same_sign = (a[N-1] == b[N-1]);

    always @* begin
        if (same_sign) begin

            res = a_abs + b_abs;
            res[N-1] = a[N-1];
        end else begin

            if (a_abs > b_abs) begin
                res = a_abs - b_abs;
                res[N-1] = 0;
            end else if (b_abs > a_abs) begin
                res = b_abs - a_abs;
                res[N-1] = 0;
            end else begin
                res = {N{1'b0}};

            end
        end
        c = res;
    end
endmodule

