module fixed_point_subtractor #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];

    always @* begin
        if (sign_a == sign_b) begin

            res = a - b;
            res[N-1] = sign_a;
        end else begin

            if (sign_a) begin

                res = b - a;
                res[N-1] = 1;
            end else begin

                res = a - b;
                res[N-1] = 0;
            end
        end


        if (res == 0)
            res[N-1] = 0;
    end

    assign c = res;
endmodule

