    reg [8:0] a_exponent, b_exponent, sum_exponent;
    reg a_sign, b_sign, z_sign;
    reg [23:0] a_mantissa, b_mantissa;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;
    reg [22:0] z_mantissa;
    reg [8:0] z_exponent;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b000;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            sum_exponent <= 0;
            z_sign <= 0;
            z_exponent <= 0;
            z_mantissa <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            z <= 0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 9'b0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 9'b0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin 
                    if ((a_exponent == 9'hff && |a_mantissa) || (b_exponent == 9'hff && |b_mantissa)) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 9'hff;
                        z_mantissa <= 23'h000001;
                        counter <= 3'b111;
                    end else if ((a_exponent == 9'hff && |a_mantissa) || (b_exponent == 9'hff && |b_mantissa)) begin
                        if ((a_exponent == 9'hff && |a_mantissa) && (b_exponent == 9'hff && |b_mantissa)) begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 9'hff;
                            z_mantissa <= 23'h000001;
                        end else if (a_exponent == 9'hff && |a_mantissa) begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 9'hff;
                            z_mantissa <= 23'h0;
                        end else if (b_exponent == 9'hff && |b_mantissa) begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 9'hff;
                            z_mantissa <= 23'h0;
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 9'hff;
                            z_mantissa <= 23'h0;
                        end
                        counter <= 3'b111;
                    end else if ((a_exponent == 9'b0 && a_mantissa == 24'd0) && (b_exponent == 9'b0 && b_mantissa == 24'd0)) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 9'b0;
                        z_mantissa <= 24'd0;
                        counter <= 3'b111;
                    end else if (a_exponent == 9'b0 && a_mantissa == 24'd0) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 9'b0;
                        z_mantissa <= 24'd0;
                        counter <= 3'b111;
                    end else if (b_exponent == 9'b0 && b_mantissa == 24'd0) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 9'b0;
                        z_mantissa <= 24'd0;
                        counter <= 3'b111;
                    end else begin
                        sum_exponent <= a_exponent + b_exponent - 9'd127;
                        product <= a_mantissa * b_mantissa;
                        counter <= 3'b010;
                    end
                end
                3'b010: begin 
                    integer i;
                    reg [49:0] temp_product;
                    reg [4:0] shift_amount;
                    temp_product = product;
                    shift_amount = 0;
                    for (i = 49;
 i >= 0;
 i = i -1) begin
                        if (temp_product[i]) begin
                            shift_amount = 49 - i;
                            break;
                        end
                    end
                    product <= temp_product << shift_amount;
                    sum_exponent <= sum_exponent + shift_amount;
                    counter <= 3'b011;
                end
                3'b011: begin 
                    z_mantissa <= product[48:26];
                    guard_bit <= product[25];
                    round_bit <= product[24];
                    sticky <= |product[23:0];
                    counter <= 3'b100;
                end
                3'b100: begin 
                    if (guard_bit && (round_bit || sticky || z_mantissa[0])) begin
                        z_mantissa <= z_mantissa + 1;
                        if (z_mantissa == 23'h7fffff) begin
                            sum_exponent <= sum_exponent + 1;
                            z_mantissa <= 23'h0;
                        end
                    end
                    counter <= 3'b101;
                end
                3'b101: begin 
                    if (sum_exponent >= 9'd255) begin
                        z_exponent <= 9'd255;
                        z_mantissa <= 23'd0;
                    end else if (sum_exponent <= 9'd0) begin
                        z_exponent <= 9'd0;
                        z_mantissa <= 23'd0;
                    end else begin
                        z_exponent <= sum_exponent;
                    end
                    counter <= 3'b110;
                end
                3'b110: begin 
                    z <= {z_sign, z_exponent, z_mantissa};
                    counter <= 3'b111;
                end
                default: begin
                    counter <= 3'b000;
                    z <= 32'd0;
                end
            endcase
        end
    end
endmodule

