    reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
    wire [PTR_WIDTH-1:0] wptr_gray, rptr_gray;
    wire [PTR_WIDTH-1:0] rptr_sync, wptr_sync;


    reg [PTR_WIDTH-1:0] rptr_gray_sync0, rptr_gray_sync1;
    reg [PTR_WIDTH-1:0] wptr_gray_sync0, wptr_gray_sync1;


    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin),
        .rdata(rdata)
    );


    assign wptr_gray = (wptr_bin >> 1) ^ wptr_bin;
    assign rptr_gray = (rptr_bin >> 1) ^ rptr_bin;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_sync0 <= 0;
            rptr_gray_sync1 <= 0;
        end else begin
            rptr_gray_sync0 <= rptr_gray;
            rptr_gray_sync1 <= rptr_gray_sync0;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_sync0 <= 0;
            wptr_gray_sync1 <= 0;
        end else begin
            wptr_gray_sync0 <= wptr_gray;
            wptr_gray_sync1 <= wptr_gray_sync0;
        end
    end


    assign rptr_sync = gray2bin(rptr_gray_sync1);
    assign wptr_sync = gray2bin(wptr_gray_sync1);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            wptr_bin <= 0;
        else if (winc && !wfull)
            wptr_bin <= wptr_bin + 1;
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            rptr_bin <= 0;
        else if (rinc && !rempty)
            rptr_bin <= rptr_bin + 1;
