            gray2bin = bin;
        end
    endfunction


    always @(posedge wclk) begin
        wfull <= (wptr_bin[PTR_WIDTH-1] != rptr_sync[PTR_WIDTH-1]) && (wptr_bin[PTR_WIDTH-2:0] == rptr_sync[PTR_WIDTH-2:0]);
    end

    always @(posedge rclk) begin
        rempty <= (rptr_bin == wptr_sync);
    end

