module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);
    reg [2:0] SP;

    reg [3:0] stack_mem [0:3];


    always @(posedge Clk) begin
        if (EN) begin
            if (Rst) begin

                SP <= 3'd4;
                stack_mem[0] <= 4'b0;
                stack_mem[1] <= 4'b0;
                stack_mem[2] <= 4'b0;
                stack_mem[3] <= 4'b0;
                dataOut <= 4'b0;
                EMPTY <= 1'b1;
                FULL <= 1'b0;
            end else begin
                reg [2:0] next_SP = SP;
                reg next_EMPTY, next_FULL;
                next_EMPTY = (next_SP == 3'd4);
                next_FULL = (next_SP == 3'd0);

                if (RW) begin

                    if (!next_FULL && !next_EMPTY) begin
                        dataOut <= stack_mem[next_SP];
                        stack_mem[next_SP] <= 4'b0;
                        next_SP = next_SP + 1;
                        next_EMPTY = (next_SP + 1 == 3'd4);
                        next_FULL = (next_SP + 1 == 3'd0);
                    end
                end else begin

                    if (!next_FULL) begin
                        stack_mem[next_SP - 1] <= dataIn;
                        next_SP = next_SP - 1;
                        next_FULL = (next_SP - 1 == 3'd0);
                        next_EMPTY = (next_SP - 1 == 3'd4);
                    end
                end

                SP <= next_SP;
                EMPTY <= next_EMPTY;
                FULL <= next_FULL;
            end
        end
    end
endmodule

