module traffic_light(
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);
    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state, next_state;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= idle;
        else
            state <= next_state;
    end


    always @* begin
        case (state)
            idle: next_state = s1_red;
            s1_red: next_state = (cnt == 3) ? s3_green : s1_red;
            s2_yellow: next_state = (cnt == 3) ? s1_red : s2_yellow;
            s3_green: next_state = (cnt == 3) ? s2_yellow : s3_green;
            default: next_state = idle;
        endcase
    end


    always @(negedge rst_n or posedge clk) begin
        if (!rst_n)
            cnt <= 8'd10;
        else begin
            if (pass_request && green)
                cnt <= 8'd10;
            else if (p_green && !green)
                cnt <= 8'd60;
            else if (p_yellow && !yellow)
                cnt <= 8'd5;
            else if (p_red && !red)
                cnt <= 8'd10;
            else
                cnt <= cnt - 8'd1;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red, p_yellow, p_green} <= 3'b0;
            {red, yellow, green} <= 3'b0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
            case (state)
                s1_red: {red, yellow, green} <= 3'b100;
                s2_yellow: {red, yellow, green} <= 3'b010;
                s3_green: {red, yellow, green} <= 3'b001;
                default: {red, yellow, green} <= 3'b000;
            endcase
        end
    end

    assign clock = cnt;

endmodule

