    reg [31:0] res;
    wire [32:0] sum_add, sum_sub;

    always @(*) begin
        case (aluc)
            ADD: begin
                sum_add = {1'b0, a} + {1'b0, b};
                res = sum_add[31:0];
                carry = sum_add[32];
                overflow = (~a[31] & ~b[31] & res[31]) | (a[31] & b[31] & ~res[31]);
            end
            ADDU: begin
                sum_add = {1'b0, a} + {1'b0, b};
                res = sum_add[31:0];
                carry = sum_add[32];
                overflow = 0;
            end
            SUB: begin
                sum_sub = {1'b0, a} - {1'b0, b};
                res = sum_sub[31:0];
                carry = sum_sub[32];
                overflow = (a[31] != b[31]) && (res[31] != a[31]);
