            SUBU: begin
                sum_sub = {1'b0, a} - {1'b0, b};
                res = sum_sub[31:0];
                carry = sum_sub[32];
                overflow = 0;
            end
            AND: begin
                res = a & b;
                carry = 0;
                overflow = 0;
            end
            OR: begin
                res = a | b;
                carry = 0;
                overflow = 0;
            end
            XOR: begin
                res = a ^ b;
                carry = 0;
                overflow = 0;
            end
            NOR: begin
                res = ~(a | b);
                carry = 0;
                overflow = 0;
            end
            SLT: begin
                res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                carry = 0;
                overflow = 0;
            end
            SLTU: begin
                res = (a < b) ? 32'd1 : 32'd0;
                carry = 0;
                overflow = 0;
            end
            SLL: begin
                res = b << a[4:0];
                carry = 0;
                overflow = 0;
            end
            SRL: begin
                res = b >> a[4:0];
                carry = 0;
                overflow = 0;
            end
            SRA: begin
                res = $signed(b) >>> a[4:0];
                carry = 0;
                overflow = 0;
            end
            SLLV: begin
                res = b << a[4:0];
                carry = 0;
                overflow = 0;
            end
            SRLV: begin
                res = b >> a[4:0];
                carry = 0;
                overflow = 0;
            end
            SRAV: begin
