                carry = 0;
                overflow = 0;
            end
            LUI: begin
                res = {a[15:0], 16'b0};
                carry = 0;
                overflow = 0;
            end
            default: begin
                res = 32'bz;
                carry = 0;
                overflow = 0;
            end
        endcase
        r = res;
    end

    assign zero = (res == 32'b0);
    assign negative = res[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? res[0] : 1'bz;

