module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] saved_dividend;
    reg [7:0] saved_divisor;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg dividend_sign;
    reg divisor_sign;
    reg quotient_sign_reg;
    reg remainder_sign_reg;
    reg [8:0] abs_dividend;
    reg [8:0] abs_divisor;
    reg [8:0] NEG_DIVISOR;
    reg [15:0] saved_result;
    wire [8:0] temp_remainder;
    wire carry_out;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            cnt <= 0;
            start_cnt <= 0;
            SR <= 0;
            saved_result <= 0;
            quotient <= 0;
            remainder <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            quotient_sign_reg <= 0;
            remainder_sign_reg <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                saved_dividend <= dividend;
                saved_divisor <= divisor;
                dividend_sign <= sign ? dividend[7] : 1'b0;
                divisor_sign <= sign ? divisor[7] : 1'b0;
                quotient_sign_reg <= sign ? (dividend[7] ^ divisor[7]) : 1'b0;
                remainder_sign_reg <= sign ? dividend[7] : 1'b0;

                if (sign) begin
                    abs_dividend <= dividend[7] ? -{1'b0, dividend} : {1'b0, dividend};
                    abs_divisor <= divisor[7] ? -{1'b0, divisor} : {1'b0, divisor};
                end else begin
                    abs_dividend <= {1'b0, dividend};
                    abs_divisor <= {1'b0, divisor};
                end

                SR <= {abs_dividend, 1'b0} << 1;
                NEG_DIVISOR <= -abs_divisor;
                cnt <= 4'd1;
                start_cnt <= 1;
                res_valid <= 0;
            end

            if (start_cnt) begin
                if (cnt == 4'd8) begin
                    start_cnt <= 0;
                    cnt <= 0;
                    quotient <= quotient_sign_reg ? -quotient : quotient;
                    remainder <= remainder_sign_reg ? -remainder : remainder;
                    result <= {remainder, quotient};
                    res_valid <= 1;
                end else begin
                    temp_remainder = SR[15:8] - NEG_DIVISOR;
                    carry_out = ~temp_remainder[8];
                    quotient <= {quotient[6:0], carry_out};
                    SR <= {SR[14:8], carry_out, SR[7:0]};
                    cnt <= cnt + 1;
                end
            end

            if (res_valid && opn_valid)
                res_valid <= 0;
        end
    end

    always @(posedge clk) begin
        if (start_cnt && !cnt[3])
            remainder <= SR[15:8];
    end
endmodule

