module div_16bit(A, B, result, odd);
    input [15:0] A;
    input [7:0] B;
    output reg [15:0] result;
    output reg [15:0] odd;

    reg [15:0] a_reg;
    reg [7:0] b_reg;

    always @(A or B) begin
        a_reg <= A;
        b_reg <= B;
    end

    always @(A or B) begin
        integer i;
        reg [7:0] rem;
        reg [15:0] quo;
        reg [7:0] divisor;
        divisor = b_reg;
        rem = a_reg[15:8];
        quo = 0;

        for (i = 0;
 i < 16;
 i = i + 1) begin
            if (rem >= divisor) begin
                quo[15 - i] = 1'b1;
                rem = rem - divisor;
            end else begin
                quo[15 - i] = 1'b0;
            end



            rem = {rem[6:0], a_reg[15 - i - 8]};
        end

        result = quo;
        odd = {8'b0, rem};
    end
endmodule

