        for (j=0;
 j<16;
 j=j+1) begin
            integer k;
            reg [15:0] product;
            product = 1;
            for (k=j+1;
 k<16;
 k=k+1)
                product = product & p[k];
            G = G | (g[j] & product);
        end
    end


    reg [15:0] carry;
    integer m;
    always @(*) begin
        for (int i=1;
 i<16;
 i=i+1) begin
            carry[i] = g[i-1];
            for (m=0;
 m < i;
 m=m+1) begin
