module fixed_point_adder #(parameter Q = 1, parameter N = 4) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a, sign_b;
    wire [N-2:0] a_mag, b_mag;

    assign sign_a = a[N-1];
    assign sign_b = b[N-1];
    assign a_mag = a[N-2:0];
    assign b_mag = b[N-2:0];

    always @(*) begin
        if (sign_a == sign_b) begin

            res = {sign_a, a_mag + b_mag};
        end else begin

            if (a_mag > b_mag) begin
                res = {1'b0, a_mag - b_mag};
            end else begin
                res = {1'b0, b_mag - a_mag};
            end
        end
    end

    assign c = res;
endmodule

