module fixed_point_subtractor #(parameter Q=1, parameter N=4) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg signed [N-1:0] a_signed, b_signed;
    reg signed [N-1:0] a_abs, b_abs;
    reg signed [N-1:0] sum_abs;

    always @* begin
        a_signed = $signed(a);
        b_signed = $signed(b);
        res = 0;
        if (a_signed[N-1] == b_signed[N-1]) begin

            res = a_signed - b_signed;
        end else begin

            a_abs = a_signed[N-1] ? -$signed(a) : a_signed;
            b_abs = b_signed[N-1] ? -$signed(b) : b_signed;
            sum_abs = a_abs + b_abs;
            res = ($signed(a) > $signed(b)) ? sum_abs : -sum_abs;
        end

        if (res == 0) res[N-1] = 0;
        c = res;
    end
endmodule

