    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;
    reg [9:0] initial_exponent;
    reg a_is_nan, a_is_inf, a_is_zero;
    reg b_is_nan, b_is_inf, b_is_zero;
    reg special_case;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            a_mantissa <= 24'b0;
            b_mantissa <= 24'b0;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            product <= 50'b0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            initial_exponent <= 10'b0;
            a_is_nan <= 0;
            a_is_inf <= 0;
            a_is_zero <= 0;
            b_is_nan <= 0;
            b_is_inf <= 0;
            b_is_zero <= 0;
            special_case <= 0;
