                    a_is_inf <= (a[30:23] == 8'hff) && (a[22:0] == 0);
                    a_is_zero <= (a[30:23] == 8'h00) && (a[22:0] == 0);
                    b_is_nan <= (b[30:23] == 8'hff) && (b[22:0] != 0);
                    b_is_inf <= (b[30:23] == 8'hff) && (b[22:0] == 0);
                    b_is_zero <= (b[30:23] == 8'h00) && (b[22:0] == 0);
                    special_case <= (a_is_nan || b_is_nan || 
                        (a_is_inf && (b_is_zero || b_is_inf)) || 
                        (b_is_inf && (a_is_zero || a_is_inf)) || 
                        (a_is_zero && b_is_zero));
                    if (special_case) begin
                        z_sign <= a_sign ^ b_sign;
                        if (a_is_nan || b_is_nan) begin
                            z[31:23] <= 8'hff;
                            z[22:0] <= 23'h1;
                        end else if (a_is_inf || b_is_inf) begin
                            z[31] <= a_sign ^ b_sign;
                            if (a_is_inf && b_is_zero) begin
                                z[30:23] <= 8'hff;
                                z[22:0] <= 23'h1;
                            end else if (b_is_inf && a_is_zero) begin
                                z[30:23] <= 8'hff;
                                z[22:0] <= 23'h1;
                            end else begin
                                z[30:23] <= 8'hff;
                                z[22:0] <= 23'b0;
                            end
                        end else begin
                            z[31] <= a_sign ^ b_sign;
                            z[30:23] <= 8'h00;
                            z[22:0] <= 23'b0;
                        end
                        counter <= 3'b001;
                    end else begin
                        initial_exponent <= a_exponent + b_exponent - 10'd127;
                        counter <= 3'b001;
                    end
                end

                3'b001: begin
                    product <= a_mantissa * b_mantissa;
                    counter <= 3'b010;
                end

                3'b010: begin
                    if (product[47]) begin
                        product <= product >> 1;
                        initial_exponent <= initial_exponent + 10'd1;
                    end
                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];
                    counter <= 3'b011;
