                3'b011: begin
                    if (product[47]) begin
                        z_mantissa <= product[46:23] + (guard_bit & (round_bit | sticky));
                        z_exponent <= initial_exponent + 10'd1;
                    end else begin
                        z_mantissa <= product[46:23] + (guard_bit & (round_bit | sticky));
                        z_exponent <= initial_exponent;
                    end
                    if (z_mantissa[23]) begin
                        z_mantissa <= z_mantissa >> 1;
                        z_exponent <= z_exponent + 10'd1;
                    end
                    if (z_exponent > 10'd254) begin
                        z[31] <= a_sign ^ b_sign;
                        z[30:23] <= 8'hff;
                        z[22:0] <= 23'b0;
                    end else if (z_exponent < 10'd1) begin
                        z[31] <= a_sign ^ b_sign;
                        z[30:23] <= 8'h00;
                        z[22:0] <= 23'b0;
                    end else begin
                        z[31] <= a_sign ^ b_sign;
                        z[30:23] <= z_exponent[7:0];
                        z[22:0] <= z_mantissa[22:0];
                    end
                    counter <= 3'b000;
                end

                default: counter <= 3'b000;
            endcase
        end
    end
