module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wenc,
    input wire [$clog2(DEPTH)-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire renc,
    input wire [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);
    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

    always @(posedge wclk) begin
        if (wenc)
            RAM_MEM[waddr] <= wdata;
    end

    always @(posedge rclk) begin
        if (renc)
            rdata <= RAM_MEM[raddr];
    end
endmodule

module asyn_fifo #(parameter WIDTH=8, DEPTH=16) (
    input wire wclk, rclk,
    input wire wrstn, rrstn,
    input wire winc, rinc,
    input wire [WIDTH-1:0] wdata,
    output reg wfull, rempty,
    output reg [WIDTH-1:0] rdata
);
    reg [3:0] waddr_bin, raddr_bin;
    reg [3:0] wptr, rptr, wptr_buff, rptr_buff;
    reg [3:0] wptr_syn, rptr_syn;
    wire [3:0] wptr_bin, rptr_syn_bin, rptr_bin;
    wire wen, ren;

    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr_bin[2:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr_bin[2:0]),
        .rdata(rdata)
    );

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            wptr <= 0;
            wptr_buff <= 0;
        end else begin
            if (winc && !wfull) begin
                waddr_bin <= waddr_bin + 1;
                wptr <= (wptr >> 1) ^ wptr;
            end
            wptr_buff <= wptr;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            rptr <= 0;
            rptr_buff <= 0;
        end else begin
            if (rinc && !rempty) begin
                raddr_bin <= raddr_bin + 1;
                rptr <= (rptr >> 1) ^ rptr;
            end
            rptr_buff <= rptr;
        end
    end

    reg [3:0] rptr_sync0, rptr_sync1;
    always @(posedge wclk) begin
        rptr_sync0 <= rptr_buff;
        rptr_sync1 <= rptr_sync0;
    end
    assign rptr_syn = rptr_sync1;

    reg [3:0] wptr_sync0, wptr_sync1;
    always @(posedge rclk) begin
        wptr_sync0 <= wptr_buff;
        wptr_sync1 <= wptr_sync0;
    end
    assign wptr_syn = wptr_sync1;

    function [3:0] gray2bin;
        input [3:0] gray;
        reg [3:0] bin;
        begin
            bin[3] = gray[3];
            bin[2] = gray[2] ^ bin[3];
            bin[1] = gray[1] ^ bin[2];
            bin[0] = gray[0] ^ bin[1];
            gray2bin = bin;
        end
    endfunction

    assign wptr_bin = gray2bin(wptr);
    assign rptr_syn_bin = gray2bin(rptr_syn);
    assign rptr_bin = gray2bin(rptr);

    always @(posedge wclk) begin
        wfull <= (wptr_bin - rptr_syn_bin) >= DEPTH;
    end

    always @(posedge rclk) begin
        rempty <= (rptr == wptr_syn);
    end

    assign wen = winc && !wfull;
    assign ren = rinc && !rempty;
endmodule

