module LIFObuffer(dataIn, RW, EN, Rst, Clk, EMPTY, FULL, dataOut);
    input [3:0] dataIn;
    input RW, EN, Rst, Clk;
    output reg EMPTY, FULL;
    output reg [3:0] dataOut;

    reg [3:0] stack_mem [0:3];

    reg [3:0] SP = 4;

    integer i;

    always @(posedge Clk) begin
        if (EN) begin
            if (Rst) begin

                for (i = 0;
 i < 4;
 i = i + 1)
                    stack_mem[i] <= 4'b0;
                SP <= 4;
                EMPTY <= 1'b1;
                FULL <= 1'b0;
            end else begin
                if (RW == 1'b0) begin 
                    if (~FULL) begin
                        stack_mem[SP - 1] <= dataIn;
                        SP <= SP - 1;
                    end
                end else begin 
                    if (~EMPTY) begin
                        dataOut <= stack_mem[SP];
                        stack_mem[SP] <= 4'b0;
                        SP <= SP + 1;
                    end
                end

                EMPTY <= (SP == 4);
                FULL <= (SP == 0);
            end
        end
    end
endmodule

