module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [1:0] state;
localparam IDLE = 2'b00;
localparam BUSY = 2'b01;

reg [7:0] saved_dividend_abs;
reg [7:0] saved_divisor_abs;
reg sign_dividend;
reg sign_divisor;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] NEG_DIVISOR;
reg [7:0] quotient_abs;
reg [7:0] remainder_abs;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        result <= 16'b0;
        SR <= 16'b0;
        cnt <= 0;
        start_cnt <= 0;
        saved_dividend_abs <= 0;
        saved_divisor_abs <= 0;
        sign_dividend <= 0;
        sign_divisor <= 0;
        quotient_abs <= 0;
        remainder_abs <= 0;
        NEG_DIVISOR <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (opn_valid && !res_valid) begin
                    sign_dividend <= (sign && dividend[7]);
                    sign_divisor <= (sign && divisor[7]);
                    saved_dividend_abs <= sign ? (~dividend + 1) : dividend;
                    saved_divisor_abs <= sign ? (~divisor + 1) : divisor;
                    SR <= {saved_dividend_abs << 1, 8'b0};
                    NEG_DIVISOR <= -saved_divisor_abs;
                    cnt <= 1;
                    start_cnt <= 1;
                    state <= BUSY;
                    res_valid <= 0;
                end
            end
            BUSY: begin
                if (start_cnt) begin
                    reg [7:0] remainder_part = SR[15:8];
                    reg [7:0] quotient_part = SR[7:0];
                    reg [7:0] new_remainder = remainder_part - NEG_DIVISOR;
                    reg carry_out = (new_remainder[7] == 0);
                    if (carry_out) begin
                        remainder_part = new_remainder;
                        quotient_part = (quotient_part << 1) | 1'b1;
                    end else begin
                        quotient_part = quotient_part << 1;
                    end
                    SR <= {remainder_part, quotient_part};
                    cnt <= cnt + 1;
                    if (cnt == 8) begin
                        start_cnt <= 0;
                        quotient_abs <= (sign_dividend != sign_divisor) ? (~quotient_part + 1) : quotient_part;
                        remainder_abs <= (sign_dividend) ? (~remainder_part + 1) : remainder_part;
                        result <= {remainder_abs, quotient_abs};
                        res_valid <= 1;
                        state <= IDLE;
                    end
                end
            end
        endcase
    end
end

endmodule

