module fixed_point_adder #(parameter Q=2, parameter N=8) (
    input [N-1:0] a, b,
    output reg [N-1:0] c
);
reg a_sign, b_sign;
reg [N-1:0] a_abs, b_abs;
reg [N-1:0] sum;
reg result_sign;

always @* begin
    a_sign = a[N-1];
    b_sign = b[N-1];
    a_abs = a_sign ? (-a) : a;
    b_abs = b_sign ? (-b) : b;

    if (a_sign == b_sign) begin
        sum = a_abs + b_abs;
        result_sign = a_sign;
    end else begin
        if (a_abs > b_abs) begin
            sum = a_abs - b_abs;
            result_sign = a_sign;
        end else if (b_abs > a_abs) begin
            sum = b_abs - a_abs;
            result_sign = b_sign;
        end else begin
            sum = 0;
            result_sign = 0;
        end
    end

    c = {result_sign, sum[N-2:0]};
end
endmodule

