assign b_is_nan = (b_exponent == 9'h1ff) && (b_mantissa != 0);
assign a_is_inf = (a_exponent == 9'h1ff) && (a_mantissa == 0);
assign b_is_inf = (b_exponent == 9'h1ff) && (b_mantissa == 0);
assign a_is_zero = (a_exponent == 0) && (a_mantissa == 0);
assign b_is_zero = (b_exponent == 0) && (b_mantissa == 0);

