module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wrstn,
    input wire winc,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire rrstn,
    input wire rinc,
    output wire rempty,
    output wire wfull,
    output wire [WIDTH-1:0] rdata
);
