    assign wfull = (wptr_gray == { ~rptr_gray_sync2[PTR_WIDTH-1:PTR_WIDTH-2], rptr_gray_sync2[PTR_WIDTH-3:0] });
    assign rempty = (rptr_gray == wptr_gray_sync2);


    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
