module div_16bit(A, B, result, odd);
    input [15:0] A, B;
    output reg [15:0] result, odd;
    reg [15:0] a_reg, b_reg;


    always @* begin
        a_reg = A;
        b_reg = B;
    end


    always @* begin
        reg [15:0] remainder;
        reg [15:0] quotient;
        integer i;
        reg [7:0] divisor;
        reg [15:0] dividend;

        dividend = a_reg;
        divisor = b_reg;

        remainder = dividend[15:8];

        quotient = 16'b0;

        for (i = 1;
 i <= 16;
 i = i + 1) begin
            if (i == 1) begin

                if (remainder >= divisor) begin
                    quotient[15] = 1'b1;
                    remainder = remainder - divisor;
                end
            end else begin

                integer bit_index;
                bit_index = 7 - (i - 1);

                remainder = {remainder[7:0], dividend[bit_index]};
                if (remainder >= divisor) begin
                    quotient[16 - i] = 1'b1;
                    remainder = remainder - divisor;
                end
            end
        end


        odd = {8'b0, remainder};
        result = quotient;
    end
endmodule

