    wire [N-1:0] absolute_a = msb_a ? (~a + 1) : a;
    wire [N-1:0] absolute_b = msb_b ? (~b + 1) : b;
    wire same_sign = (msb_a == msb_b);
    wire [N-1:0] sum_abs = absolute_a + absolute_b;
    wire [N-1:0] diff_ab = absolute_a - absolute_b;
    wire [N-1:0] diff_ba = absolute_b - absolute_a;
    wire ab_gt = (absolute_a > absolute_b);
    wire ba_gt = (absolute_b > absolute_a);
    wire [N-1:0] result_magnitude = same_sign ? sum_abs :
                                    (ab_gt ? diff_ab : (ba_gt ? diff_ba : 0));
    wire result_sign = same_sign ? msb_a : (ab_gt ? 1'b0 : 1'b1);

    always @* begin
        c = {result_sign, result_magnitude[N-2:0]};
    end
endmodule

