module fixed_point_subtractor #(parameter Q=16, parameter N=32) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    reg sign_res;
    wire sign_a, sign_b;
    wire [N-1:0] abs_b, abs_a;
    wire [N-1:0] temp_diff;

    assign sign_a = a[N-1];
    assign sign_b = b[N-1];

    always @* begin
        if (sign_a == sign_b) begin

            res = a - b;
            sign_res = sign_a;

            if (res == 0)
                sign_res = 0;
        end else begin

            if (sign_a == 0 && sign_b == 1) begin

                abs_b = ~b + 1;
                if (a > abs_b) begin
                    temp_diff = a - abs_b;
                    sign_res = 0;
                end else begin
                    temp_diff = abs_b - a;
                    sign_res = 1;
                end
                res = {sign_res, temp_diff[N-2:0]};
            end else begin

                abs_a = ~a + 1;
                if (abs_a > b) begin
                    temp_diff = abs_a - b;
                    sign_res = 0;
                end else begin
                    temp_diff = b - abs_a;
                    sign_res = 1;
                end
                res = {sign_res, temp_diff[N-2:0]};
            end

            if (temp_diff == 0)
                sign_res = 0;
        end
        res = {sign_res, res[N-2:0]};
        c = res;
    end
endmodule

