                        if ((a_exponent == 10'h3ff) && (a_mantissa[23] == 0)) begin

                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 10'h3ff;
                            z_mantissa <= 24'h0;
                        end else if ((a_exponent == 10'h3ff) || (a_exponent == 0 && a_mantissa == 0)) begin

                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 10'h3ff;
                            z_mantissa <= 24'h0;
                        end else begin

                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 10'h3ff;
                            z_mantissa <= 24'h0;
                        end
                    end else if ((a_exponent == 0 && a_mantissa == 0) || (b_exponent == 0 && b_mantissa == 0)) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 10'h0;
                        z_mantissa <= 24'h0;
                    end else begin

                        counter <= 3'd2;
                    end
