                    counter <= 3'd5;
                end
                3'd5: begin

                    if (z_exponent >= 10'h3ff) begin

                        z_exponent <= 10'h3ff;
                        z_mantissa <= 24'h0;
                    end else if (z_exponent <= 0) begin

                        z_exponent <= 10'h0;
                        z_mantissa <= 24'h0;
                    end
                    counter <= 3'd6;
                end
                3'd6: begin

                    z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    counter <= 3'd0;
                end
                default: begin
                    counter <= 3'd0;
                end
            endcase
        end
    end

