	        S3	  :next_state = data_in?S4:IDLE;
	        S4	  :next_state = data_in?S1:S2;
	        default:next_state = IDLE;	
	    endcase
    end
end

assign sequence_detected = (curr_state ==S4) ? 1'b1 : 1'b0;

