module asyn_fifo #(parameter DEPTH = 16, WIDTH = 8) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);
    localparam PTR_WIDTH = $clog2(DEPTH);


    reg [PTR_WIDTH-1:0] waddr_bin;
    wire [PTR_WIDTH-1:0] waddr_bin_next = waddr_bin + 1;
    reg [PTR_WIDTH-1:0] wptr_gray;
    wire [PTR_WIDTH-1:0] wptr_gray_next = waddr_bin_next ^ (waddr_bin_next >> 1);
    reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;
    wire [PTR_WIDTH-1:0] wptr_gray_sync = wptr_gray_sync2;


    reg [PTR_WIDTH-1:0] raddr_bin;
    wire [PTR_WIDTH-1:0] raddr_bin_next = raddr_bin + 1;
    reg [PTR_WIDTH-1:0] rptr_gray;
    wire [PTR_WIDTH-1:0] rptr_gray_next = raddr_bin_next ^ (raddr_bin_next >> 1);
    reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;
    wire [PTR_WIDTH-1:0] rptr_gray_sync = rptr_gray_sync2;

    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(raddr_bin),
        .rdata(rdata)
    );

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            wptr_gray <= 0;
        end else if (winc && !wfull) begin
            waddr_bin <= waddr_bin_next;
            wptr_gray <= wptr_gray_next;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            rptr_gray <= 0;
        end else if (rinc && !rempty) begin
            raddr_bin <= raddr_bin_next;
            rptr_gray <= rptr_gray_next;
        end
    end

    always @(posedge rclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end

    always @(posedge wclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end

    assign rempty = (rptr_gray == wptr_gray_sync);
    assign wfull = (wptr_gray == {~rptr_gray_sync[PTR_WIDTH-1:PTR_WIDTH-2], rptr_gray_sync[PTR_WIDTH-3:0]});
    assign wenc = winc && !wfull;
    assign renc = rinc && !rempty;

endmodule

module dual_port_RAM #(parameter DEPTH = 16, WIDTH = 8) (
    input wire wclk,
    input wire wenc,
    input wire [$clog2(DEPTH)-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
