module pulse_detect(clk, rst_n, data_in, data_out);
    input clk, rst_n, data_in;
    output reg data_out;

    reg [1:0] state;
    parameter IDLE = 2'b00, S1 = 2'b01, S2 = 2'b10;

    always @(posedge clk, negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            data_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in) begin
                        state <= S1;
                    end else begin
                        state <= IDLE;
                    end
                    data_out <= 0;
                end
                S1: begin
                    if (!data_in) begin
                        state <= S2;
                        data_out <= 1;
                    end else begin
                        state <= IDLE;
                        data_out <= 0;
                    end
                end
                S2: begin
                    state <= IDLE;
                    data_out <= 0;
                end
                default: begin
                    state <= IDLE;
                    data_out <= 0;
                end
            endcase
        end
    end
endmodule

