module traffic_light(
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);
    parameter idle = 2'b00,
              s1_red = 2'b01,
              s2_yellow = 2'b10,
              s3_green = 2'b11;

    reg [1:0] state, next_state;
    reg p_red, p_yellow, p_green;
    reg [7:0] cnt;
    reg [1:0] prev_state;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end


    always @(*) begin
        case (state)
            idle:      next_state = s1_red;
            s1_red:    next_state = (cnt == 0) ? s3_green : s1_red;
            s2_yellow: next_state = (cnt == 0) ? s1_red : s2_yellow;
            s3_green:  next_state = (cnt == 0) ? s2_yellow : s3_green;
            default:   next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            prev_state <= idle;
        end else begin
            prev_state <= state;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (state != prev_state) begin
                case (state)
                    s1_red:    cnt <= 10;
                    s3_green:  cnt <= 60;
                    s2_yellow: cnt <= 5;
                    default:   cnt <= cnt;
                endcase
            end else begin
                cnt <= cnt - 1;
            end

            if (state == s3_green && pass_request && p_green) begin
                if (cnt > 10)
                    cnt <= 10;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
            case (state)
                s1_red: begin
                    red <= 1;
                    yellow <= 0;
                    green <= 0;
                end
                s2_yellow: begin
                    red <= 0;
                    yellow <= 1;
                    green <= 0;
                end
                s3_green: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 1;
                end
                default: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 0;
                end
            endcase
        end
    end

    assign clock = cnt;

endmodule

