module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [15:0] SR;
    reg [7:0] abs_dividend, abs_divisor;
    reg [7:0] NEG_DIVISOR;
    reg [3:0] cnt;
    reg start_cnt;
    wire [7:0] quotient = SR[7:0];
    wire [7:0] remainder = SR[15:8];

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            SR <= 0;
            NEG_DIVISOR <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid && !start_cnt) begin

                abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                NEG_DIVISOR <= -abs_divisor;


                SR <= {abs_dividend, 1'b0} << 1;
                start_cnt <= 1;
                cnt <= 1;
            end else if (start_cnt && !res_valid) begin
                if (cnt < 8) begin

                    reg [8:0] temp_remainder = {1'b0, SR[15:8]} - {1'b0, NEG_DIVISOR};
                    reg carry_out = temp_remainder[8];

                    if (carry_out) begin
                        SR[15:8] <= temp_remainder[7:0];
                    end
                    SR <= {SR[14:0], carry_out};
                    cnt <= cnt + 1;
                end else begin

                    start_cnt <= 0;
                    res_valid <= 1;
                    result <= {remainder, quotient};
                end
            end

            if (res_valid && (cnt >= 8)) begin
                res_valid <= 0;
            end
        end
    end
endmodule

