    reg [9:0] accumulator;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            count <= 2'b00;
            accumulator <= 10'b0;
            valid_out <= 1'b0;
            data_out <= 10'b0;
        end else begin
            valid_out <= 1'b0;
            if (valid_in) begin
                if (count == 2'd3) begin
                    data_out <= accumulator + data_in;
                    valid_out <= 1'b1;
                    count <= 2'b00;
                    accumulator <= 10'b0;
                end else begin
                    accumulator <= accumulator + data_in;
                    count <= count + 1;
                end
            end
        end
    end

endmodule

