module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

reg [N-1:0] res;
wire a_MSB = a[N-1];
wire b_MSB = b[N-1];

always @* begin
    if (a_MSB == b_MSB) begin

        res = a + b;

        if (res[N-1] != a_MSB) begin
            res = a_MSB ? {1'b1, {(N-1){1'b0}}} : {1'b0, {(N-1){1'b1}}};
        end
    end else begin

        reg [N-1:0] abs_a, abs_b;
        abs_a = a_MSB ? (~a + 1) : a;
        abs_b = b_MSB ? (~b + 1) : b;
        if (abs_a > abs_b) begin
            res = a - b;
            res[N-1] = 1'b0;
        end else begin
            res = b - a;
        end
    end
end

assign c = res;

endmodule

