module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);

    always @(*) begin
        if (same_sign) begin
            res = a - b;

            if (res == 0)
                c = 0;
            else
                c = res;
        end else begin

            reg [N-1:0] abs_a = sign_a ? (~a + 1) : a;
            reg [N-1:0] abs_b = sign_b ? (~b + 1) : b;
            reg [N-1:0] sum_abs = abs_a + abs_b;
            reg sign_res;

            if (sum_abs == 0)
                sign_res = 0;
            else
                sign_res = (abs_a > abs_b) ? sign_a : sign_b;

            res = {sign_res, sum_abs[N-2:0]};

            c = (sum_abs == 0) ? 0 : res;
        end
    end
endmodule

