module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [8:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [22:0] rounded_mantissa;
    reg [8:0] adjusted_exponent;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'd0;
            z <= 32'd0;
        end else begin
            case (counter)
                3'd0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (|a[30:23]) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_mantissa <= (|b[30:23]) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                    z <= 32'd0;

                    if (a[30:23] == 8'hFF || b[30:23] == 8'hFF) begin

                        z_sign <= a_sign ^ b_sign;
                        if ((a[30:23] == 8'hFF && |a[22:0]) || (b[30:23] == 8'hFF && |b[22:0])) begin
                            z[31] <= z_sign;
                            z[30:23] <= 8'hFF;
                            z[22:0] <= 23'h1;
                        end else begin
                            z[31] <= z_sign;
                            z[30:23] <= 8'hFF;
                            z[22:0] <= 23'h0;
                        end
                    end else if (a == 32'h0 || b == 32'h0) begin

                        z_sign <= a_sign ^ b_sign;
                        z[31] <= z_sign;
                        z[30:23] <= 8'h0;
                        z[22:0] <= 23'h0;
                    end else begin
                        counter <= counter + 1;
                    end
                end

                3'd1: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= counter + 1;
                end

                3'd2: begin

                    if (product[47]) begin
                        z_mantissa <= product[46:24];
                        z_exponent <= a_exponent + b_exponent - 9'd127 + 9'd1;
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end else begin
                        z_mantissa <= product[45:23];
                        z_exponent <= a_exponent + b_exponent - 9'd127;
                        guard_bit <= product[22];
                        round_bit <= product[21];
                        sticky <= |product[20:0];
                    end
                    counter <= counter + 1;
                end

                3'd3: begin

                    rounded_mantissa <= z_mantissa;
                    if (guard_bit && (round_bit || sticky || z_mantissa[0])) begin
                        rounded_mantissa <= z_mantissa + 1;
                        adjusted_exponent <= (rounded_mantissa == 23'd0) ? z_exponent + 1 : z_exponent;
                    end else begin
                        adjusted_exponent <= z_exponent;
                    end
                    counter <= counter + 1;
                end

                3'd4: begin

                    if (adjusted_exponent > 9'h1FE) begin
                        z[31] <= z_sign;
                        z[30:23] <= 8'hFF;
                        z[22:0] <= 23'h0;
                    end else if (adjusted_exponent < 9'h1) begin
                        z[31] <= z_sign;
                        z[30:23] <= 8'h0;
                        z[22:0] <= 23'h0;
                    end else begin
                        z[31] <= z_sign;
                        z[30:23] <= adjusted_exponent[7:0];
                        z[22:0] <= rounded_mantissa;
                    end
                    counter <= 3'd0;
                end

                default: counter <= 3'd0;
            endcase
        end
    end
