module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output reg wfull,
    output reg rempty,
    output wire [WIDTH-1:0] rdata
);
    reg [3:0] wptr_bin, rptr_bin;

    reg [3:0] wptr_gray, rptr_gray;
    reg [3:0] wptr_gray_prev, rptr_gray_prev;
    reg [3:0] rptr_gray_syn1, rptr_gray_syn2;
    reg [3:0] wptr_gray_syn1, wptr_gray_syn2;
    wire [3:0] waddr_bin, raddr_bin;
    wire [3:0] rptr_bin_syn;


    wire full_condition, empty_condition;
    assign full_condition = (wptr_gray[3] != rptr_gray_syn2[3]) &&
                            (wptr_gray[2] != rptr_gray_syn2[2]) &&
                            (wptr_gray[1:0] == rptr_gray_syn2[1:0]);
    assign empty_condition = (rptr_gray == wptr_gray_syn2);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_bin <= 0;
            wptr_gray <= 0;
            wfull <= 0;
            {wptr_gray_syn1, wptr_gray_syn2} <= 0;
        end else begin
            wptr_gray_syn1 <= rptr_gray;
            wptr_gray_syn2 <= wptr_gray_syn1;

            if (winc && !wfull) begin
                wptr_bin <= wptr_bin + 1;
                wptr_gray <= wptr_bin ^ (wptr_bin >> 1);
            end

            wfull <= full_condition;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_bin <= 0;
            rptr_gray <= 0;
            rempty <= 0;
            {rptr_gray_syn1, rptr_gray_syn2} <= 0;
        end else begin
            rptr_gray_syn1 <= wptr_gray;
            rptr_gray_syn2 <= rptr_gray_syn1;

            if (rinc && !rempty) begin
                rptr_bin <= rptr_bin + 1;
                rptr_gray <= rptr_bin ^ (rptr_bin >> 1);
            end

            rempty <= empty_condition;
        end
    end


    assign waddr_bin = wptr_bin[2:0];
    assign raddr_bin = rptr_bin[2:0];


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin),
        .rdata(rdata)
    );
endmodule


