function [3:0] binary_to_gray(input [3:0] bin);
    binary_to_gray = bin ^ (bin >> 1);
endfunction


function [3:0] gray_to_binary(input [3:0] gray);
    reg [3:0] bin;
    integer i;
    begin
        bin[3] = gray[3];
        for (i = 2;
 i >= 0;
 i = i - 1)
            bin[i] = bin[i+1] ^ gray[i];
        gray_to_binary = bin;
    end
endfunction

