module traffic_light(
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);
    parameter idle = 2'd0;
    parameter s1_red = 2'd1;
    parameter s2_yellow = 2'd2;
    parameter s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            idle: next_state = s1_red;
            s1_red: next_state = (cnt == 0) ? s3_green : s1_red;
            s3_green: next_state = (cnt == 0) ? s2_yellow : s3_green;
            s2_yellow: next_state = (cnt == 0) ? s1_red : s2_yellow;
            default: next_state = idle;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
            case (state)
                s1_red: begin
                    if (next_state == s3_green)
                        cnt <= 8'd60;
                    else if (cnt != 0)
                        cnt <= cnt - 1;
                end
                s3_green: begin
                    if (pass_request)
                        cnt <= 8'd10;
                    else if (next_state == s2_yellow)
                        cnt <= 8'd5;
                    else if (cnt != 0)
                        cnt <= cnt - 1;
                end
                s2_yellow: begin
                    if (next_state == s1_red)
                        cnt <= 8'd10;
                    else if (cnt != 0)
                        cnt <= cnt - 1;
                end
                default: begin
                    cnt <= 8'd10;
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end

    assign clock = cnt;

endmodule

