    reg [7:0] remainder_high, remainder_low;
    reg [7:0] temp_remainder;
    reg [3:0] highest_bit_high, highest_bit_low;
    reg [15:0] temp_result = 0;
    reg [15:0] temp_odd = 0;


    remainder_high = a_reg[15:8];
    highest_bit_high = 0;
    for (i = 7;
 i >= 0;
 i = i - 1) begin
        if (a_reg[7:0][i]) highest_bit_high = i;
    end


    temp_remainder = remainder_high - b_reg;
    if (remainder_high >= b_reg) begin
        temp_result[15] = 1;
        temp_odd[7:0] = temp_remainder;
    end else begin
        temp_odd[7:0] = remainder_high;
    end


    highest_bit_low = 0;
    for (i = 7;
 i >= 0;
 i = i - 1) begin
        if (a_reg[7:0][i]) highest_bit_low = i;
    end

