    if (remainder_low >= {8'b0, b_reg}) begin
        temp_result[14] = 1;
        temp_odd[15:8] = remainder_low - {8'b0, b_reg};
    end else begin
        temp_odd[15:8] = remainder_low;
    end

    result = temp_result;
    odd = temp_odd;
