module adder_32bit (
    input [32:1] A,
    input [32:1] B,
    output [32:1] S,
    output C32
);
    wire [16:1] G_lower, G_upper;
    wire [16:1] P_lower, P_upper;
    wire C16;


    cla_16bit lower (
        .A(A[16:1]),
        .B(B[16:1]),
        .C_in(1'b0),
        .S(S[16:1]),
        .G(G_lower),
        .P(P_lower),
        .C_out()  
    );


    cla_16bit upper (
        .A(A[32:17]),
        .B(B[32:17]),
        .C_in(G_lower),
        .S(S[32:17]),
        .G(G_upper),
        .P(P_upper),
        .C_out()
    );


    assign C32 = G_lower + (P_lower & G_upper);
endmodule

module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input C_in,
    output [16:1] S,
    output G,
    output P,
    output C_out
);
    wire [16:1] G_bit, P_bit;
    wire [17:1] C;

    assign G_bit[1] = A[1] & B[1];
    assign P_bit[1] = A[1] ^ B[1];
    assign C[1] = G_bit[1] | (P_bit[1] & C_in);

    genvar i;
    generate
        for (i = 2;
 i <= 16;
 i = i + 1) begin : cla
            assign G_bit[i] = A[i] & B[i];
            assign P_bit[i] = A[i] ^ B[i];

            assign C[i] = G_bit[i-1] | (P_bit[i-1] & C[i-1]);
        end
    endgenerate


    assign P = &P_bit[16:1];
    assign G = G_bit[16] | (P_bit[16] & C[16]);
    assign S = P_bit ^ C[16:1];
    assign C_out = G | (P & C_in);
endmodule

