module fixed_point_adder #(parameter Q=2, parameter N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg a_sign, b_sign;
    reg [N-1:0] a_abs, b_abs;

    always @(*) begin
        a_sign = a[N-1];
        b_sign = b[N-1];

        if (a_sign == b_sign) begin

            res = a + b;

            if (res[N-1] != a_sign) begin
                res = a_sign ? { {N-1{1'b1}} } : {1'b0, {N-1{1'b1}} };
            end
        end else begin

            a_abs = a_sign ? (-a) : a;
            b_abs = b_sign ? (-b) : b;

            if (a_abs > b_abs)
                res = a_abs - b_abs;
            else
                res = b_abs - a_abs;


            res[N-1] = 1'b0;
        end
        c = res;
    end
endmodule

