module float_multi(
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg [23:0] a_mantissa_full, b_mantissa_full, z_mantissa_full;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b000;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            z_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            a_mantissa_full <= 0;
            b_mantissa_full <= 0;
            z_mantissa_full <= 0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    counter <= counter + 1;
                end
                3'b001: begin 
                    if ((a_exponent == 8'hff && |a_mantissa) || (b_exponent == 8'hff && |b_mantissa)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if ((a_exponent == 0 && a_mantissa == 0) || (b_exponent == 0 && b_mantissa == 0)) begin
                        z <= {a_sign ^ b_sign, 31'b0};
                    end else begin
                        counter <= counter + 1;
                    end
                end
                3'b010: begin 
                    if (a_exponent == 0)
                        a_mantissa_full <= {1'b0, a_mantissa};
                    else
                        a_mantissa_full <= {1'b1, a_mantissa};
                    if (b_exponent == 0)
                        b_mantissa_full <= {1'b0, b_mantissa};
                    else
                        b_mantissa_full <= {1'b1, b_mantissa};
                    product <= a_mantissa_full * b_mantissa_full;
                    counter <= counter + 1;
                end
                3'b011: begin 
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                    if (product[47:46] >= 2) begin
                        z_mantissa_full <= product[47:24] >> 1;
                        z_exponent <= z_exponent + 8'd1;
                    end else begin
                        z_mantissa_full <= product[47:24];
                    end
                    counter <= counter + 1;
                end
                3'b100: begin 
                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];
                    counter <= counter + 1;
                end
                3'b101: begin 
                    if (guard_bit && (round_bit || sticky || z_mantissa_full[0])) begin
                        z_mantissa_full <= z_mantissa_full + 1;
                        if (z_mantissa_full == 24'h100000) begin 
                            z_mantissa_full <= 24'h0;
                            z_exponent <= z_exponent + 8'd1;
                        end
                    end
                    counter <= counter + 1;
                end
                3'b110: begin 
                    if (z_exponent >= 8'hff) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if (z_exponent == 0) begin
                        z <= {a_sign ^ b_sign, 31'b0};
                    end else begin
                        z <= {a_sign ^ b_sign, z_exponent, z_mantissa_full[22:0]};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end
endmodule

