module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);
    localparam PTR_WIDTH = $clog2(DEPTH);
    reg [PTR_WIDTH-1:0] waddr_bin, raddr_bin;
    reg [PTR_WIDTH-1:0] wptr, rptr;
    reg [PTR_WIDTH-1:0] rptr_sync1, rptr_sync2;
    reg [PTR_WIDTH-1:0] wptr_sync1, wptr_sync2;

    assign rempty = (rptr == rptr_sync2);
    assign wfull = (wptr[PTR_WIDTH-1] != wptr_sync2[PTR_WIDTH-1]) &&
                   (wptr[PTR_WIDTH-2] != wptr_sync2[PTR_WIDTH-2]) &&
                   (wptr[PTR_WIDTH-3:0] == wptr_sync2[PTR_WIDTH-3:0]);

    always @(posedge wclk) begin
        if (~wrstn) begin
            waddr_bin <= 0;
        end else if (winc && !wfull) begin
            waddr_bin <= waddr_bin + 1;
        end
    end

    always @(posedge rclk) begin
        if (~rrstn) begin
            raddr_bin <= 0;
        end else if (rinc && !rempty) begin
            raddr_bin <= raddr_bin + 1;
        end
    end

    always @(posedge wclk) begin
        if (~wrstn) begin
            wptr <= 0;
        end else begin
            wptr <= (waddr_bin >> 1) ^ waddr_bin;
        end
    end

    always @(posedge rclk) begin
        if (~rrstn) begin
            rptr <= 0;
        end else begin
            rptr <= (raddr_bin >> 1) ^ raddr_bin;
        end
    end

    always @(posedge wclk) begin
        if (~wrstn) begin
            rptr_sync1 <= 0;
            rptr_sync2 <= 0;
        end else begin
            rptr_sync1 <= rptr;
            rptr_sync2 <= rptr_sync1;
        end
    end

    always @(posedge rclk) begin
        if (~rrstn) begin
            wptr_sync1 <= 0;
            wptr_sync2 <= 0;
        end else begin
            wptr_sync1 <= wptr;
            wptr_sync2 <= wptr_sync1;
        end
    end

    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram_inst (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin),
        .rdata(rdata)
    );
endmodule

