        if (!rst_n) begin
            cnt <= 2'b0;
            data_reg <= 4'b0;
            valid_out <= 1'b0;
            dout <= 1'b0;
        end else begin
            if (cnt == 2'd3) begin
                data_reg <= d;
                cnt <= 2'd0;
                valid_out <= 1'b1;
