module traffic_light (
    input         rst_n,
    input         clk,
    input         pass_request,
    output [7:0]  clock,
    output        red,
    output        yellow,
    output        green
);

    parameter [1:0] idle     = 2'd0,
                    s1_red   = 2'd1,
                    s2_yellow= 2'd2,
                    s3_green = 2'd3;


    reg [1:0]   state, next_state;
    reg [7:0]   cnt;
    reg         p_red, p_yellow, p_green;


    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle:     state <= s1_red;
                s1_red:   if (cnt == 0) state <= s3_green;
                s3_green: if (cnt == 0) state <= s2_yellow;
                s2_yellow:if (cnt == 0) state <= s1_red;
                default:  state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            case (state)
                s1_red:   cnt <= 8'd3;
                s3_green: cnt <= 8'd3;
                s2_yellow:cnt <= 8'd3;
                default:  cnt <= cnt - 8'd1;
            endcase
            if (pass_request && green) cnt <= 8'd10;
            if (!green && p_green)      cnt <= 8'd60;
            if (!yellow && p_yellow)    cnt <= 8'd5;
            if (!red && p_red)          cnt <= 8'd10;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red, p_yellow, p_green} <= 3'b000;
        end else begin
            {p_red, p_yellow, p_green} <= 
                (state == s1_red)   ? 3'b100 :
                (state == s2_yellow) ? 3'b010 :
                (state == s3_green)  ? 3'b001 : 3'b000;
        end
    end


    assign {red, yellow, green} = {p_red, p_yellow, p_green};

endmodule

