module serial2parallel (
    input wire clk,
    input wire rst_n,
    input wire din_serial,
    input wire din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);
    reg [3:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 4'd0;
            dout_parallel <= 8'd0;
            dout_valid <= 1'b0;
        end else begin
            dout_valid <= 1'b0;
            if (din_valid) begin
                dout_parallel[7 - cnt] <= din_serial;
                cnt <= cnt + 4'd1;
            end
            if (din_valid && (cnt + 4'd1) == 4'd8) begin
                dout_valid <= 1'b1;
                cnt <= 4'd0;
            end
        end
    end
endmodule

