module signal_generator (
    input clk,
    input rst_n,
    output reg [4:0] wave
);
    reg state;
    reg [4:0] next_wave;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 1'b0;
            wave <= 5'b0;
        end else begin
            case (state)
                1'b0: begin
                    next_wave = wave + 1;
                    wave <= next_wave;
                    if (next_wave == 5'd31)
                        state <= 1'b1;
                end
                1'b1: begin
                    next_wave = wave - 1;
                    wave <= next_wave;
                    if (next_wave == 5'd0)
                        state <= 1'b0;
                end
            endcase
        end
    end
endmodule

