module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [15:0] SR;

reg [3:0] cnt;
reg start_cnt;
reg [7:0] absolute_dividend;
reg [7:0] absolute_divisor;
reg [7:0] saved_dividend;
reg [7:0] saved_divisor;
reg opn_sign;
reg dividend_sign;
reg divisor_sign;
reg quotient_sign;
reg dividend_was_negative;
reg divisor_was_negative;

wire [7:0] remainder_upper = SR[15:8];
wire [7:0] quotient_lower = SR[7:0];
wire [7:0] sub_result;
wire carry_out;

assign sub_result = remainder_upper - absolute_divisor;
assign carry_out = ~sub_result[7];


always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        start_cnt <= 0;
        cnt <= 0;
        SR <= 0;
        saved_dividend <= 0;
        saved_divisor <= 0;
        opn_sign <= 0;
        dividend_sign <= 0;
        divisor_sign <= 0;
        quotient_sign <= 0;
        dividend_was_negative <= 0;
        divisor_was_negative <= 0;
        result <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            saved_dividend <= dividend;
            saved_divisor <= divisor;
            opn_sign <= sign;

            if (sign) begin

                if (dividend[7]) begin
                    absolute_dividend <= -dividend;
                end else begin
                    absolute_dividend <= dividend;
                end

                if (divisor[7]) begin
                    absolute_divisor <= -divisor;
                end else begin
                    absolute_divisor <= divisor;
                end


                dividend_sign <= dividend[7];
                divisor_sign <= divisor[7];
                quotient_sign <= dividend[7] ^ divisor[7];
                dividend_was_negative <= dividend[7];
                divisor_was_negative <= divisor[7];
            end else begin

                absolute_dividend <= dividend;
                absolute_divisor <= divisor;
                quotient_sign <= 0;
                dividend_was_negative <= 0;
                divisor_was_negative <= 0;
                dividend_sign <= 0;
                divisor_sign <= 0;
            end


            SR <= {absolute_dividend, 8'b0} << 1;
            cnt <= 4'd1;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt && !res_valid) begin
            if (carry_out) begin
                SR[15:8] <= sub_result;
                SR[7:0] <= {quotient_lower[6:0], 1'b1};
            end else begin
                SR[15:8] <= remainder_upper;
                SR[7:0] <= {quotient_lower[6:0], 1'b0};
            end

            if (cnt == 4'd8) begin

                start_cnt <= 0;
                cnt <= 0;

                if (opn_sign) begin

                    if (quotient_sign) begin
                        result[7:0] <= -SR[7:0];
                    end else begin
                        result[7:0] <= SR[7:0];
                    end

                    if (dividend_was_negative) begin
                        result[15:8] <= -SR[15:8];
                    end else begin
                        result[15:8] <= SR[15:8];
                    end
                end else begin

                    result[7:0] <= SR[7:0];
                    result[15:8] <= SR[15:8];
                end
                res_valid <= 1;
            end else begin
                cnt <= cnt + 4'd1;
            end
        end else begin
            res_valid <= 0;
        end
    end
end

endmodule

