module div_16bit(A, B, result, odd);
    input [15:0] A;
    input [7:0] B;
    output reg [15:0] result;
    output reg [15:0] odd;

    reg [15:0] a_reg;
    reg [7:0] b_reg;

    always @(A, B) begin

        a_reg <= A;
        b_reg <= B;
    end

    always @(A, B) begin

        reg [7:0] remainder;
        reg [15:0] quotient;
        integer i;

        remainder = 8'b0;
        quotient = 16'b0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin

            remainder = {remainder[6:0], a_reg[15]};
            a_reg = {a_reg[14:0], 1'b0};


            if (remainder >= b_reg) begin
                remainder = remainder - b_reg;
                quotient[i] = 1'b1;
            end else begin
                quotient[i] = 1'b0;
            end
        end

        result = quotient;
        odd = {remainder, 8'b0};

    end
endmodule

