module fixed_point_adder #(parameter Q=2, N=4) (
    input [N-1:0] a, b,
    output [N-1:0] c
);
reg [N-1:0] res;
reg [N-1:0] a_abs, b_abs;
reg [N:0] sum_abs;
reg [N-1:0] sub_res;
wire a_greater, b_greater;


always @(*) begin
    a_abs = a[N-1] ? (~a + 1) : a;
    b_abs = b[N-1] ? (~b + 1) : b;
end

assign sum_abs = a_abs + b_abs;


assign a_greater = (a_abs > b_abs);
assign b_greater = (b_abs > a_abs);

always @(*) begin
    if (a[N-1] == b[N-1]) begin

        res = {a[N-1], sum_abs[N-1:0]};
    end else begin

        if (a_greater) begin
            sub_res = a_abs - b_abs;
            res = {1'b0, sub_res};
        end else if (b_greater) begin
            sub_res = b_abs - a_abs;
            res = {1'b1, sub_res};
        end else begin
            res = {1'b0, {N{1'b0}}};

        end
    end
end

assign c = res;
endmodule

