module fixed_point_subtractor #(parameter Q=4, parameter N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c = 0
);
    reg [N-1:0] res;
    reg sign_a, sign_b;
    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] sum_abs;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        if (sign_a == sign_b) begin
            res = a - b;
        end else begin

            abs_a = sign_a ? (-a) : a;
            abs_b = sign_b ? (-b) : b;
            sum_abs = abs_a + abs_b;

            res = sign_a ? (-sum_abs) : sum_abs;
        end

        if (res == 0) begin
            res[N-1] = 0;
        end
        c = res;
    end
endmodule

