                            if (a_exponent == 9'h0) begin
                                z <= 32'h7fc00000;

                            end else begin
                                z <= {a_sign ^ b_sign, 8'hff, 23'b0};

                            end
                        end
                    end else if (a_exponent == 9'h0 || b_exponent == 9'h0) begin

                        if ((a_exponent == 9'h0 && a_mantissa == 24'h0) || 
                            (b_exponent == 9'h0 && b_mantissa == 24'h0)) begin
                            z <= {a_sign ^ b_sign, 31'b0};

                        end else begin

                            product <= a_mantissa * b_mantissa;
                            exp_sum <= a_exponent + b_exponent - 9'd127;
                            counter <= counter + 1;
                        end
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        exp_sum <= a_exponent + b_exponent - 9'd127;
                        counter <= counter + 1;
                    end
                end
                3'b010: begin

                    if (product[47]) begin
                        product_normal <= product >> 1;
                        exp_sum <= exp_sum + 9'd1;
                    end else begin
                        product_normal <= product;
                    end

                    guard_bit <= product_normal[24];
                    round_bit <= product_normal[23];
