                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};

                    end else if (exp_sum <= 9'h0) begin
                        z <= {a_sign ^ b_sign, 31'b0};

                    end else begin

                        z <= {a_sign ^ b_sign, exp_sum[7:0], rounded_mantissa[22:0]};
