module fsm (
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);
    parameter S0 = 3'd0, S1 = 3'd1, S2 = 3'd2, S3 = 3'd3, S4 = 3'd4;
    reg [2:0] current_state, next_state;


    always @(posedge CLK, posedge RST) begin
        if (RST)
            current_state <= S0;
        else
            current_state <= next_state;
    end


    always @(*) begin
        case (current_state)
            S0: next_state = IN ? S1 : S0;
            S1: next_state = IN ? S4 : S2;
            S2: next_state = IN ? S3 : S0;
            S3: next_state = IN ? S4 : S0;
            S4: next_state = IN ? S1 : S0;
            default: next_state = S0;
        endcase
    end


    always @(*) begin
        case (current_state)
            S0: MATCH = 1'b0;
            S1: MATCH = IN ? 1'b1 : 1'b0;
            S2: MATCH = 1'b0;
            S3: MATCH = 1'b0;
            S4: MATCH = IN ? 1'b1 : 1'b0;
            default: MATCH = 1'b0;
        endcase
    end

