module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wenc,
    input wire [$clog2(DEPTH)-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire renc,
    input wire [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);
    reg [WIDTH-1:0] ram_mem [0:DEPTH-1];

    always @(posedge wclk) begin
        if (wenc)
            ram_mem[waddr] <= wdata;
    end

    always @(posedge rclk) begin
        if (renc)
            rdata <= ram_mem[raddr];
    end
endmodule

module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output reg wfull,
    output reg rempty,
    output reg [WIDTH-1:0] rdata
);
    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH + 1;

    wire [ADDR_WIDTH-1:0] waddr, raddr;
    wire wen, ren;
    reg [PTR_WIDTH-1:0] waddr_bin, raddr_bin;
    reg [PTR_WIDTH-1:0] waddr_gray, raddr_gray;
    reg [PTR_WIDTH-1:0] waddr_gray_sync1, waddr_gray_sync2;
    reg [PTR_WIDTH-1:0] raddr_gray_sync1, raddr_gray_sync2;

    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr),
        .rdata(rdata)
    );

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
        end else begin
            if (wen)
                waddr_bin <= waddr_bin + 1;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
        end else begin
            if (ren)
                raddr_bin <= raddr_bin + 1;
        end
    end

    function [PTR_WIDTH-1:0] bin2gray(input [PTR_WIDTH-1:0] bin);
        bin2gray = (bin >> 1) ^ bin;
    endfunction

    assign waddr_gray = bin2gray(waddr_bin);
    assign raddr_gray = bin2gray(raddr_bin);

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            {waddr_gray_sync2, waddr_gray_sync1} <= 0;
        end else begin
            waddr_gray_sync2 <= raddr_gray;
            waddr_gray_sync1 <= waddr_gray_sync2;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            {raddr_gray_sync2, raddr_gray_sync1} <= 0;
        end else begin
            raddr_gray_sync2 <= waddr_gray;
            raddr_gray_sync1 <= raddr_gray_sync2;
        end
    end

    wire [PTR_WIDTH-1:0] waddr_gray_next = bin2gray(waddr_bin + 1);

    assign rempty = (waddr_gray == raddr_gray_sync2);
    assign wfull = (waddr_gray_next[PTR_WIDTH-1] != raddr_gray_sync2[PTR_WIDTH-1]) &&
                   (waddr_gray_next[PTR_WIDTH-2] != raddr_gray_sync2[PTR_WIDTH-2]) &&
                   (waddr_gray_next[PTR_WIDTH-3:0] == raddr_gray_sync2[PTR_WIDTH-3:0]);

    assign wen = winc && !wfull;
    assign ren = rinc && !rempty;

    assign waddr = waddr_bin[ADDR_WIDTH-1:0];
    assign raddr = raddr_bin[ADDR_WIDTH-1:0];

endmodule

