module LIFObuffer(
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [2:0] SP;


always @(posedge Clk) begin
    if (Rst) begin

        integer i;
        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 4'b0;
        SP <= 3'b100;

        EMPTY <= 1'b1;
        FULL <= 1'b0;
    end else begin
        if (EN) begin
            reg [2:0] next_SP;
            next_SP = SP;

            if (RW) begin 
                if (SP != 3'b100) begin 
                    next_SP = SP + 3'b001;
                    dataOut <= stack_mem[SP];
                end
            end else begin 
                if (SP != 3'b000) begin 
                    next_SP = SP - 3'b001;
                    stack_mem[SP - 3'b001] <= dataIn;
                end
            end

            SP <= next_SP;
            EMPTY <= (next_SP == 3'b100);
            FULL <= (next_SP == 3'b000);
        end
    end
end

endmodule

