module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;
reg [1:0] next_state;

localparam STATE0 = 2'd0;
localparam STATE1 = 2'd1;
localparam STATE2 = 2'd2;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= STATE0;
        data_out <= 1'b0;
    end else begin
        state <= next_state;
        data_out <= (next_state == STATE2);
    end
end

always @* begin
    case (state)
        STATE0: next_state = data_in ? STATE1 : STATE0;
        STATE1: next_state = data_in ? STATE1 : STATE2;
        STATE2: next_state = STATE0;
        default: next_state = STATE0;
    endcase
end

endmodule

