module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);
    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [31:0] res;
    reg carry_out, overflow_out;

    wire [32:0] sum_33bit;

    always @(*) begin
        case (aluc)
            ADD: begin
                sum_33bit = {1'b0, a} + {1'b0, b};
                res = sum_33bit[31:0];
                carry_out = sum_33bit[32];
                overflow_out = sum_33bit[32] ^ sum_33bit[31];
            end
            ADDU: begin
                sum_33bit = {1'b0, a} + {1'b0, b};
                res = sum_33bit[31:0];
                carry_out = sum_33bit[32];
                overflow_out = 1'b0;
            end
            SUB: begin
                sum_33bit = {1'b0, a} - {1'b0, b};
                res = sum_33bit[31:0];
                carry_out = ~sum_33bit[32];
                overflow_out = sum_33bit[32] ^ sum_33bit[31];
            end
            SUBU: begin
                sum_33bit = {1'b0, a} - {1'b0, b};
                res = sum_33bit[31:0];
                carry_out = ~sum_33bit[32];
                overflow_out = 1'b0;
            end
            AND: begin
                res = a & b;
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            OR: begin
                res = a | b;
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            XOR: begin
                res = a ^ b;
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            NOR: begin
                res = ~(a | b);
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            SLT: begin
                res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            SLTU: begin
                res = (a < b) ? 32'd1 : 32'd0;
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            SLL: begin
                res = b << a[4:0];
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            SRL: begin
                res = b >> a[4:0];
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            SRA: begin
                res = $signed(b) >>> a[4:0];
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            SLLV: begin
                res = b << a[4:0];
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            SRLV: begin
                res = b >> a[4:0];
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            SRAV: begin
                res = $signed(b) >>> a[4:0];
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            LUI: begin
                res = {a[15:0], 16'b0};
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
            default: begin
                res = 32'bz;
                carry_out = 1'b0;
                overflow_out = 1'b0;
            end
        endcase
    end

    assign r = res;
    assign zero = (res == 32'b0);
    assign negative = res[31];
    assign carry = carry_out;
    assign overflow = overflow_out;
    assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

endmodule

