    reg start_cnt;
    reg [8:0] NEG_DIVISOR;



    wire [8:0] sub_result = SR_upper - NEG_DIVISOR;
    wire carry_out = (SR_upper >= NEG_DIVISOR);

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 1'b0;
            start_cnt <= 1'b0;
            cnt <= 5'd0;
            SR_upper <= 9'd0;
            SR_lower <= 8'd0;
            abs_dividend <= 8'd0;
            abs_divisor <= 8'd0;
            sign_dividend <= 1'b0;
            sign_divisor <= 1'b0;
            result <= 16'd0;
        end else begin
            if (opn_valid && !res_valid) begin 
                sign_dividend <= sign ? dividend[7] : 1'b0;
                sign_divisor <= sign ? divisor[7] : 1'b0;
                abs_dividend <= sign ? ((dividend[7]) ? -dividend : dividend) : dividend;
