                    cnt <= cnt + 5'd1;
                end else begin 
                    start_cnt <= 1'b0;
                    if (sign) begin 
                        if (sign_dividend ^ sign_divisor)
                            SR_lower <= -SR_lower;
                        if (sign_dividend)
                            SR_upper <= -SR_upper;
                    end
                    result <= {SR_upper, SR_lower};

                    res_valid <= 1'b1;
                end
            end
