module div_16bit(A, B, result, odd);
input [15:0] A;
input [7:0] B;
output reg [15:0] result;
output reg [15:0] odd;

reg [15:0] a_reg, b_reg;

always @(A, B) begin
    a_reg = A;
    b_reg = B;
end

always @(A, B) begin
    reg [7:0] remainder_high, remainder_low;
    reg [7:0] quotient_high, quotient_low;


    if (a_reg[15:8] >= b_reg) begin
        quotient_high = 8'hFF;
        remainder_high = a_reg[15:8] - b_reg;
    end else begin
        quotient_high = 8'h00;
        remainder_high = a_reg[15:8];
    end


    if (remainder_high >= b_reg) begin
        quotient_low = 8'hFF;
        remainder_low = remainder_high - b_reg;
    end else begin
        quotient_low = 8'h00;
        remainder_low = remainder_high;
    end


    result = {quotient_high, quotient_low};
    odd = {remainder_low, 8'h00};
end

endmodule

