    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);
    wire [4:0] temp_sum;        // Temporary 5-bit sum to store initial result
    wire [3:0] corrected_sum;   // Adjusted BCD sum
    wire carry_out;             // Corrected carry-out

