module fixed_point_adder #(parameter Q=8, N=16) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg [N-2:0] abs_a, abs_b;

    always @(*) begin

        abs_a = a[N-1] ? (~a[N-2:0] + 1) : a[N-2:0];
        abs_b = b[N-1] ? (~b[N-2:0] + 1) : b[N-2:0];


        if (a[N-1] == b[N-1]) begin

            res = {a[N-1], abs_a + abs_b};
        end else begin

            if (abs_a > abs_b) begin
                res = {1'b0, abs_a - abs_b};

            end else if (abs_b > abs_a) begin
                res = {1'b1, abs_b - abs_a};

            end else begin
                res = {1'b0, {(N-1){1'b0}}};

            end
        end
        c = res;
    end
endmodule

