module fixed_point_subtractor #(parameter Q=4, N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-2:0] int_a = a[N-2 : N-Q-1];
    wire [N-2:0] int_b = b[N-2 : N-Q-1];
    wire [Q-1:0] frac_a = a[Q-1 : 0];
    wire [Q-1:0] frac_b = b[Q-1 : 0];
    wire sign_res;

    always @(*) begin
        if (sign_a == sign_b) begin

            res = a - b;
            sign_res = sign_a;
        end else begin

            wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
            wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;
            if (sign_a) begin

                if (abs_a >= abs_b) begin
                    res = abs_a - abs_b;
                    sign_res = 1'b1;

                end else begin
                    res = abs_b - abs_a;
                    sign_res = 1'b0;

                end
            end else begin

                res = abs_a + abs_b;
                sign_res = 1'b0;

            end
        end

        if (res == 0)
            sign_res = 1'b0;
        res[N-1] = sign_res;
        c = res;
    end
endmodule

