    wire                overflow, underflow;


    assign a_is_nan = (a_exponent == 8'hFF) && (a_mantissa != 0);
    assign b_is_nan = (b_exponent == 8'hFF) && (b_mantissa != 0);
    assign a_is_inf = (a_exponent == 8'hFF) && (a_mantissa == 0);
    assign b_is_inf = (b_exponent == 8'hFF) && (b_mantissa == 0);
    assign a_is_zero = (a_exponent == 0) && (a_mantissa == 0);
    assign b_is_zero = (b_exponent == 0) && (b_mantissa == 0);
    assign overflow = (z_exponent >= 255);
    assign underflow = (z_exponent == 0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            z_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            z_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
