            case (counter)
                0: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= 1;
                end
                1: begin 
                    if (a_is_nan || b_is_nan) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 8'hFF;
                        z_mantissa <= 24'h000001;
                    end else if (a_is_inf || b_is_inf) begin
                        if ((a_is_inf && b_is_zero) || (b_is_inf && a_is_zero)) begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hFF;
                            z_mantissa <= 24'h000001;
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hFF;
                            z_mantissa <= 0;
                        end
                    end else if (a_is_zero || b_is_zero) begin
                        if ((a_is_zero && b_is_inf) || (b_is_zero && a_is_inf)) begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hFF;
                            z_mantissa <= 24'h000001;
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 0;
                            z_mantissa <= 0;
                        end
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        counter <= 2;
                    end
                end
                2: begin 
                    counter <= 3;
                end
                3: begin 
                    if (product[48]) begin
                        z_mantissa <= product[48:25];
                        z_exponent <= a_exponent + b_exponent - 8'd127 + 1;
                        guard_bit <= product[24];
                        round_bit <= product[23];
                        sticky <= |product[22:0];
                    end else begin
                        z_mantissa <= product[47:24];
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                        guard_bit <= product[24];
                        round_bit <= product[23];
                        sticky <= |product[22:0];
                    end
                    counter <= 4;
                end
                4: begin 
                    if (guard_bit && (round_bit || sticky)) begin
                        z_mantissa <= z_mantissa + 1;
                    end
                    if (z_mantissa[23] && guard_bit) begin 
                        z_mantissa <= 0;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= 5;
                end
                5: begin 
                    if (overflow) begin
                        z_sign <= z_sign;
                        z_exponent <= 8'hFF;
                        z_mantissa <= 0;
                    end else if (underflow) begin
                        z_sign <= z_sign;
                        z_exponent <= 0;
                        z_mantissa <= 0;
                    end
                    counter <= 6;
                end
                6: begin 
                    z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    counter <= 0;
                end
                default: counter <= 0;
            endcase
        end
    end
endmodule

