module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);

    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(raddr_bin),
        .rdata(rdata)
    );


    reg [3:0] waddr_bin;
    wire [3:0] wptr_gray;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) waddr_bin <= 0;
        else if (winc && !wfull) waddr_bin <= waddr_bin + 1;
    end
    assign wptr_gray = (waddr_bin >> 1) ^ waddr_bin;


    reg [3:0] raddr_bin;
    wire [3:0] rptr_gray;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) raddr_bin <= 0;
        else if (rinc && !rempty) raddr_bin <= raddr_bin + 1;
    end
    assign rptr_gray = (raddr_bin >> 1) ^ raddr_bin;


    reg [3:0] rptr_sync0, rptr_sync1;
    reg [3:0] wptr_sync0, wptr_sync1;
    reg [3:0] wptr, rptr;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) wptr <= 0;
        else wptr <= wptr_gray;
    end
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) rptr <= 0;
        else rptr <= rptr_gray;
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_sync0 <= 0;
            rptr_sync1 <= 0;
        end else begin
            rptr_sync0 <= rptr;
            rptr_sync1 <= rptr_sync0;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_sync0 <= 0;
            wptr_sync1 <= 0;
        end else begin
            wptr_sync0 <= wptr;
            wptr_sync1 <= wptr_sync0;
        end
    end


    assign wfull = (wptr[3] != rptr_sync1[3]) && 
                   (wptr[2] != rptr_sync1[2]) && 
                   (wptr[1:0] == rptr_sync1[1:0]);
    assign rempty = (wptr_sync1 == rptr);


    assign wenc = winc && !wfull;
    assign renc = rinc && !rempty;
endmodule


module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wenc,
    input wire [$clog2(DEPTH)-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire renc,
    input wire [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);
    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];


    always @(posedge wclk) begin
        if (wenc) RAM_MEM[waddr] <= wdata;
    end


    always @(posedge rclk) begin
        if (renc) rdata <= RAM_MEM[raddr];
    end
endmodule

