module LIFObuffer(
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);
    reg [3:0] stack_mem [0:3];

    reg [2:0] SP;

    wire empty = (SP == 4);
    wire full = (SP == 0);

    integer i;

    always @(posedge Clk) begin
        if (Rst) begin
            SP <= 4;
            for (i = 0;
 i < 4;
 i = i + 1)
                stack_mem[i] <= 4'b0;
            EMPTY <= 1'b1;
            FULL <= 1'b0;
        end else begin
            if (EN) begin
                if (RW) begin 
                    if (~FULL) begin
                        if (SP == 3'd0) begin
                            dataOut <= stack_mem[3];
                        end else begin
                            dataOut <= stack_mem[SP-1];
                        end
                        stack_mem[SP-1] <= 4'b0;
                        SP <= SP + 1;
                    end
                end else begin 
                    if (~FULL) begin
                        stack_mem[SP-1] <= dataIn;
                        SP <= SP - 1;
                    end
                end
            end
            EMPTY <= (SP == 4);
            FULL <= (SP == 0);
        end
    end
endmodule

