module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    parameter IDLE = 2'b00,
              S1   = 2'b01,
              S2   = 2'b10;

    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            data_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in == 1'b0)
                        state <= S1;
                    else
                        state <= IDLE;
                    data_out <= 0;
                end
                S1: begin
                    if (data_in == 1'b1)
                        state <= S2;
                    else
                        state <= IDLE;
                    data_out <= 0;
                end
                S2: begin
                    if (data_in == 1'b0) begin
                        state <= IDLE;
                        data_out <= 1'b1;
                    end else begin
                        state <= S2;
                        data_out <= 1'b0;
                    end
                end
                default: begin
                    state <= IDLE;
                    data_out <= 0;
                end
            endcase
        end
    end
endmodule

