module radix2_div (
    input wire clk,
    input wire rst,
    input wire sign,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] saved_dividend;
    reg [7:0] saved_divisor;
    reg [8:0] abs_dividend;

    reg [8:0] abs_divisor;

    reg [8:0] neg_divisor;

    reg [16:0] SR;

    reg [3:0] cnt;

    reg start_cnt;

    reg [7:0] quotient;
    reg [7:0] remainder;
    reg rem_sign;

    reg quot_sign;

    wire [8:0] temp_sum;


    assign temp_sum = SR[16:9] + neg_divisor;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            result <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            neg_divisor <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            rem_sign <= 0;
            quot_sign <= 0;
            quotient <= 0;
            remainder <= 0;
        end else begin
            if (res_valid) begin

                if (~opn_valid) begin
                    res_valid <= 0;
                end
            end else if (opn_valid) begin

                saved_dividend <= dividend;
                saved_divisor <= divisor;
                if (sign) begin

                    abs_dividend <= (dividend[7]) ? (-{1'b0, dividend}) : {1'b0, dividend};
                    abs_divisor <= (divisor[7]) ? (-{1'b0, divisor}) : {1'b0, divisor};
                    rem_sign <= dividend[7];
                    quot_sign <= (dividend[7] ^ divisor[7]);
                end else begin

                    abs_dividend <= {1'b0, dividend};
                    abs_divisor <= {1'b0, divisor};
                    rem_sign <= 0;
                    quot_sign <= 0;
                end

                SR <= {abs_dividend << 1, 8'b0};
                neg_divisor <= ~abs_divisor + 1;

                cnt <= 4'b1;
                start_cnt <= 1;
                res_valid <= 0;
            end

            if (start_cnt) begin
                if (cnt[3]) begin  

                    remainder <= SR[16:9] >> 1;

                    quotient <= SR[8:1];
                    result <= {remainder[7:0], quotient};
                    res_valid <= 1;
                    start_cnt <= 0;
                    cnt <= 0;
                end else begin

                    if (temp_sum[8] == 0) begin  
                        SR[16:9] <= temp_sum[8:0];
                        SR <= {temp_sum[8:0], SR[8:1]};

                    end else begin
                        SR <= SR << 1;

                    end
                    cnt <= cnt + 1;
                end
            end
        end
    end


    always @* begin
        if (res_valid) begin
            if (quot_sign) begin
                quotient = ~quotient + 1;

            end
            if (rem_sign) begin
                remainder = ~remainder + 1;

            end
        end
    end

endmodule

