module div_16bit(A, B, result, odd);
input [15:0] A;
input [7:0] B;
output reg [15:0] result;
output reg [15:0] odd;

reg [15:0] a_reg, b_reg;


always @(A, B) begin
    a_reg = A;
    b_reg = B;
end


always @(A, B) begin
    reg [15:0] rem;
    reg [15:0] quot;
    reg [7:0] divisor;
    integer i;

    divisor = b_reg;
    rem = 16'b0;
    quot = 16'b0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        rem = (rem << 1) | ((a_reg >> i) & 1);
        if (rem >= divisor) begin
            quot[i] = 1'b1;
            rem = rem - divisor;
        end else begin
            quot[i] = 1'b0;
        end
    end

    result = quot;
    odd = rem;
end

endmodule

