module fixed_point_adder #(parameter Q=4, parameter N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
    reg [N-1:0] res;
    reg res_sign;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire [N-1:0] abs_a = a_sign ? (~a + 1) : a;
    wire [N-1:0] abs_b = b_sign ? (~b + 1) : b;
    wire [N-1:0] sum_magnitude;
    reg sum_sign;
    localparam MAX_MAG = (1 << (N-1)) - 1;

    always @* begin
        if (a_sign == b_sign) begin
            sum_magnitude = abs_a + abs_b;
            sum_sign = a_sign;

            if (sum_magnitude > MAX_MAG) begin
                sum_magnitude = MAX_MAG;
                sum_sign = 0;
            end
        end else begin
            if (abs_a > abs_b) begin
                sum_magnitude = abs_a - abs_b;
                sum_sign = a_sign;
            end else if (abs_b > abs_a) begin
                sum_magnitude = abs_b - abs_a;
                sum_sign = b_sign;
            end else begin
                sum_magnitude = 0;
                sum_sign = 0;
            end
        end
        res = {sum_sign, sum_magnitude};
    end

    assign c = res;
endmodule

