module fixed_point_subtractor #(
    parameter Q = 2,
    parameter N = 4
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a, sign_b;
    reg [N-1:0] a_abs, b_abs, sum_abs;
    reg sign_res;

    always @* begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        if (sign_a == sign_b) begin 
            res = a - b;
            sign_res = sign_a;
        end else begin 
            if (sign_a == 1'b0 && sign_b == 1'b1) begin 
                a_abs = a;
                b_abs = -b;
            end else begin 
                a_abs = -a;
                b_abs = b;
            end
            sum_abs = a_abs + b_abs;

            sign_res = (a_abs > b_abs) ? 1'b0 : 1'b1;
            res = {sign_res, sum_abs[N-2:0]};
        end

        if (res == 0) begin
            res[N-1] = 0;
        end
        c = res;
    end
endmodule

