    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [8:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg guard_bit, round_bit, sticky;
    reg [49:0] product;

    wire a_is_nan, b_is_nan;
    wire a_is_inf, b_is_inf;
    wire a_is_zero, b_is_zero;

    assign a_is_nan = (a_exponent == 8'hff) && (a_mantissa != 23'd0);
    assign b_is_nan = (b_exponent == 8'hff) && (b_mantissa != 23'd0);
    assign a_is_inf = (a_exponent == 8'hff) && (a_mantissa == 23'd0);
    assign b_is_inf = (b_exponent == 8'hff) && (b_mantissa == 23'd0);
    assign a_is_zero = (a_exponent == 8'd0) && (a_mantissa == 23'd0);
    assign b_is_zero = (b_exponent == 8'd0) && (b_mantissa == 23'd0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b000;
            z <= 32'd0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            a_exponent <= 8'd0;
            b_exponent <= 8'd0;
            a_mantissa <= 24'd0;
            b_mantissa <= 24'd0;
            z_exponent <= 9'd0;
            z_mantissa <= 24'd0;
            guard_bit <= 1'b0;
            round_bit <= 1'b0;
            sticky <= 1'b0;
            product <= 50'd0;
        end else begin
            case (counter)
                3'b000: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] != 8'd0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_mantissa <= (b[30:23] != 8'd0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                    counter <= 3'b001;
                end
                3'b001: begin
                    z_sign <= a_sign ^ b_sign;
                    if (a_is_nan || b_is_nan) begin
                        z_mantissa <= 24'h000001;
                        z_exponent <= 9'h1FF;
                        z <= {z_sign, 8'hFF, z_mantissa[22:0]};
                        counter <= 3'b111;
                    end else if ((a_is_inf && b_is_zero) || (b_is_inf && a_is_zero)) begin
                        z_mantissa <= 24'h000001;
                        z_exponent <= 9'h1FF;
                        z <= {z_sign, 8'hFF, z_mantissa[22:0]};
                        counter <= 3'b111;
                    end else if (a_is_inf || b_is_inf) begin
                        z_exponent <= 9'h1FF;
                        z_mantissa <= 24'd0;
                        z <= {z_sign, 8'hFF, z_mantissa[22:0]};
                        counter <= 3'b111;
                    end else if (a_is_zero || b_is_zero) begin
                        z_exponent <= 9'd0;
                        z_mantissa <= 24'd0;
                        z <= {z_sign, 8'd0, z_mantissa[22:0]};
                        counter <= 3'b111;
                    end else begin
                        counter <= 3'b010;
                    end
                end
                3'b010: begin
                    product <= a_mantissa * b_mantissa;
                    counter <= 3'b011;
                end
                3'b011: begin
                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 9'd127 + 9'd1;
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 9'd127;
                    end
                    counter <= 3'b100;
                end
                3'b100: begin
                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];
                    z_mantissa <= product[46:24];
                    counter <= 3'b101;
                end
                3'b101: begin
                    if (guard_bit && (round_bit || sticky)) begin
                        z_mantissa <= z_mantissa + 1;
                        if (z_mantissa == 24'h7FFFFF) begin
                            z_mantissa <= 24'd0;
                            z_exponent <= z_exponent + 9'd1;
                        end
                    end else if (guard_bit && !round_bit && !sticky) begin
                        if (z_mantissa[0]) begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end
                    counter <= 3'b110;
                end
                3'b110: begin
                    if (z_exponent >= 9'd255) begin
                        z_exponent <= 9'd255;
                        z_mantissa <= 24'd0;
                    end else if (z_exponent <= 9'd0) begin
                        z_exponent <= 9'd0;
                        z_mantissa <= 24'd0;
                    end
                    counter <= 3'b111;
                end
                3'b111: begin
                    z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    counter <= 3'b000;
                end
                default: begin
                    counter <= 3'b000;
                end
            endcase
        end
    end

