module sequence_detector(clk, reset_n, data_in, sequence_detected);
    input clk, reset_n, data_in;
    output wire sequence_detected;

    reg [2:0] state, next_state;


    parameter IDLE = 3'b000,
              S1   = 3'b001,
              S2   = 3'b010,
              S3   = 3'b011,
              S4   = 3'b100;


    always @(posedge clk) begin
        if (~reset_n)
            state <= IDLE;
        else
            state <= next_state;
    end


    always @(*) begin
        case (state)
            IDLE: next_state = data_in ? S1 : IDLE;
            S1:   next_state = data_in ? S1 : S2;
            S2:   next_state = data_in ? IDLE : S3;
            S3:   next_state = data_in ? S4 : IDLE;
            S4:   next_state = data_in ? S1 : IDLE;
            default: next_state = IDLE;
        endcase
    end


    assign sequence_detected = (state == S4);

endmodule

