module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output reg rempty,
    output reg wfull,
    output wire [WIDTH-1:0] rdata
);
    localparam DEPTH_ADDR = $clog2(DEPTH);
    localparam PTR_WIDTH = DEPTH_ADDR;

    reg [PTR_WIDTH-1:0] waddr_bin, raddr_bin;
    reg [PTR_WIDTH-1:0] wgray, rgray;
    reg [PTR_WIDTH-1:0] rptr_sync1, rptr_sync2;
    reg [PTR_WIDTH-1:0] wptr_sync1, wptr_sync2;
    wire [PTR_WIDTH-1:0] rptr_sync_bin, wptr_sync_bin;

    wire wen, ren;
    wire [PTR_WIDTH-1:0] raddr_gray;
    wire [PTR_WIDTH-1:0] waddr_gray;


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr_bin),
        .rdata(rdata)
    );


    always @(posedge wclk or negedge ~wrstn) begin
        if (~wrstn)
            waddr_bin <= 0;
        else if (wen)
            waddr_bin <= waddr_bin + 1;
    end

    assign wgray = waddr_bin ^ (waddr_bin >> 1);


    always @(posedge rclk or negedge ~rrstn) begin
        if (~rrstn)
            raddr_bin <= 0;
        else if (ren)
            raddr_bin <= raddr_bin + 1;
    end

    assign rgray = raddr_bin ^ (raddr_bin >> 1);


    always @(posedge wclk) begin
        rptr_sync1 <= rgray;
        rptr_sync2 <= rptr_sync1;
    end
    assign rptr_sync_bin = rptr_sync2;


    always @(posedge rclk) begin
        wptr_sync1 <= wgray;
        wptr_sync2 <= wptr_sync1;
    end
    assign wptr_sync_bin = wptr_sync2;


    assign rptr_sync_bin[3] = rptr_sync_bin[3];
    assign rptr_sync_bin[2] = rptr_sync_bin[3] ^ rptr_sync_bin[2];
    assign rptr_sync_bin[1] = rptr_sync_bin[2] ^ rptr_sync_bin[1];
    assign rptr_sync_bin[0] = rptr_sync_bin[1] ^ rptr_sync_bin[0];

    assign wptr_sync_bin[3] = wptr_sync_bin[3];
    assign wptr_sync_bin[2] = wptr_sync_bin[3] ^ wptr_sync_bin[2];
    assign wptr_sync_bin[1] = wptr_sync_bin[2] ^ wptr_sync_bin[1];
    assign wptr_sync_bin[0] = wptr_sync_bin[1] ^ wptr_sync_bin[0];


    always @(*) begin
        rempty = (raddr_bin == rptr_sync_bin);
        wfull = (waddr_bin[3] ^ rptr_sync_bin[3]) & 
                (waddr_bin[2] ^ rptr_sync_bin[2]) & 
                (waddr_bin[1:0] == rptr_sync_bin[1:0]);
    end


    assign wen = winc && !wfull;
    assign ren = rinc && !rempty;

