            if (Rst) begin

                for (integer i = 0;
 i < 4;
 i = i + 1)
                    stack_mem[i] <= 4'b0;
                SP <= 3'd4;
            end else begin
                if (~FULL && ~RW) begin  
                    stack_mem[SP - 1] <= dataIn;
                    SP <= SP - 1;
                end else if (~EMPTY && RW) begin  
                    dataOut <= stack_mem[SP - 1];
                    stack_mem[SP - 1] <= 4'b0;
                    SP <= SP + 1;
                end
            end
        end
    end

