module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);
    localparam idle = 2'b00,
               s1_red = 2'b01,
               s2_yellow = 2'b10,
               s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: state <= (cnt == 3) ? s3_green : s1_red;
                s3_green: state <= (cnt == 3) ? s2_yellow : s3_green;
                s2_yellow: state <= (cnt == 3) ? s1_red : s2_yellow;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green) begin
                cnt <= 10;
            end else if (!green && p_green) begin
                cnt <= 60;
            end else if (!yellow && p_yellow) begin
                cnt <= 5;
            end else if (!red && p_red) begin
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end

    assign clock = cnt;
    assign red = (state == s1_red) ? 1'b1 : p_red;
    assign yellow = (state == s2_yellow) ? 1'b1 : p_yellow;
    assign green = (state == s3_green) ? 1'b1 : p_green;

