module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output flag
);

parameter ADD = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND = 6'b100100;
parameter OR = 6'b100101;
parameter XOR = 6'b100110;
parameter NOR = 6'b100111;
parameter SLT = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL = 6'b000000;
parameter SRL = 6'b000010;
parameter SRA = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI = 6'b001111;

reg [32:0] sum;

reg [32:0] temp_sub;
reg flag_reg;


assign zero = (r == 32'b0);


assign negative = r[31];


assign flag = (aluc == SLT || aluc == SLTU) ? flag_reg : 1'bz;

always @(*) begin
    case (aluc)
        ADD: begin
            sum = {1'b0, a} + {1'b0, b};
            r = sum[31:0];
            carry = sum[32];
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
        end
        ADDU: begin
            sum = {1'b0, a} + {1'b0, b};
            r = sum[31:0];
            carry = sum[32];
            overflow = 1'b0;
        end
        SUB: begin
            temp_sub = {1'b0, a} - {1'b0, b};
            r = temp_sub[31:0];
            carry = temp_sub[32];
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
        end
        SUBU: begin
            temp_sub = {1'b0, a} - {1'b0, b};
            r = temp_sub[31:0];
            carry = temp_sub[32];
            overflow = 1'b0;
        end
        AND: r = a & b;
        OR: r = a | b;
        XOR: r = a ^ b;
        NOR: r = ~(a | b);
        SLT: begin
            r = ($signed(a) < $signed(b)) ? 32'b1 : 32'b0;

        end
        SLTU: begin
            r = (a < b) ? 32'b1 : 32'b0;

        end
        SLL: r = b << a[4:0];
        SRL: r = b >> a[4:0];
        SRA: r = $signed(b) >>> a[4:0];
        SLLV: r = b << a[4:0];
        SRLV: r = b >> a[4:0];
        SRAV: r = $signed(b) >>> a[4:0];
        LUI: r = {a[15:0], 16'b0};
        default: r = 32'bz;
    endcase
end


always @(*) begin
    case (aluc)
        SLT: flag_reg = ($signed(a) < $signed(b));
        SLTU: flag_reg = (a < b);
        default: flag_reg = 1'b0;
    endcase
end

endmodule

