module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] original_dividend;
reg [7:0] original_divisor;
reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg dividend_sign;
reg divisor_sign;
reg [8:0] NEG_DIVISOR;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        result <= 16'b0;
        original_dividend <= 8'b0;
        original_divisor <= 8'b0;
        abs_dividend <= 8'b0;
        abs_divisor <= 8'b0;
        dividend_sign <= 0;
        divisor_sign <= 0;
        SR <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 0;
        NEG_DIVISOR <= 9'b0;
    end else begin
        if (res_valid) begin
            if (opn_valid && !res_valid) begin
                res_valid <= 0;
                start_cnt <= 1;
                original_dividend <= dividend;
                original_divisor <= divisor;
                if (sign) begin
                    dividend_sign <= dividend[7];
                    divisor_sign <= divisor[7];
                    abs_dividend <= dividend[7] ? -dividend : dividend;
                    abs_divisor <= divisor[7] ? -divisor : divisor;
                end else begin
                    dividend_sign <= 0;
                    divisor_sign <= 0;
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                end
                SR <= {abs_dividend << 1, 8'b0};
                NEG_DIVISOR <= {1'b1, ~abs_divisor + 1};
                cnt <= 4'd1;
            end
        end else begin
            if (start_cnt) begin
                if (cnt < 8) begin
                    reg [8:0] temp_remainder_shifted;
                    reg [7:0] temp_quotient_shifted;
                    reg [8:0] temp_sub;
                    reg [7:0] new_remainder;
                    reg [7:0] new_quotient;

                    temp_remainder_shifted = {SR[15:8], 1'b0} | {8'b0, SR[7]};
                    temp_quotient_shifted = {SR[6:0], 1'b0};

                    temp_sub = temp_remainder_shifted - NEG_DIVISOR;

                    if (temp_sub[8] == 0) begin
                        new_remainder = temp_sub[7:0];
                        new_quotient = temp_quotient_shifted | 8'b00000001;
                    end else begin
                        new_remainder = temp_remainder_shifted[7:0];
                        new_quotient = temp_quotient_shifted;
                    end

                    SR <= {new_remainder, new_quotient};
                    cnt <= cnt + 1;
                end else begin
                    start_cnt <= 0;
                    reg [7:0] final_remainder;
                    reg [7:0] final_quotient;

                    if (sign) begin
                        final_remainder = dividend_sign ? -SR[15:8] : SR[15:8];
                        final_quotient = (dividend_sign ^ divisor_sign) ? -SR[7:0] : SR[7:0];
                    end else begin
                        final_remainder = SR[15:8];
                        final_quotient = SR[7:0];
                    end

                    result <= {final_remainder, final_quotient};
                    res_valid <= 1;
                end
            end
        end
    end
end

endmodule

