    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);
    reg [15:0] a_reg;
    reg [7:0] b_reg;


    always @(*) begin
        a_reg = A;
        b_reg = B;
    end


    integer i;
    always @(*) begin
        result = 16'b0;
        odd = 16'b0;
        reg [15:0] remainder = 0;
        reg [15:0] divisor = {8'h00, b_reg};

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            remainder = (remainder << 1) | ((a_reg >> i) & 1);
            if (remainder >= divisor) begin
                result[i] = 1'b1;
                remainder = remainder - divisor;
            end else begin
                result[i] = 1'b0;
            end
        end

        odd = remainder;
    end
endmodule

