module fixed_point_adder #(parameter Q = 4, parameter N = 8) (
    input wire [N-1:0] a, b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    wire a_MSB = a[N-1];
    wire b_MSB = b[N-1];
    wire same_sign = (a_MSB == b_MSB);


    wire [N-1:0] a_abs = a_MSB ? (~a + 1) : a;
    wire [N-1:0] b_abs = b_MSB ? (~b + 1) : b;


    wire [N-1:0] diff;
    wire result_neg;
    if (a_abs > b_abs) begin
        diff = a_abs - b_abs;
        result_neg = 1'b0;
    end else begin
        diff = b_abs - a_abs;
        result_neg = 1'b1;
    end

    always @(*) begin
        if (same_sign) begin
            res = a + b;
        end else begin
            res = {result_neg, diff[N-2:0]};
        end
    end

    assign c = res;

endmodule

