module LIFObuffer(
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);
    reg [3:0] stack_mem [0:3];

    reg [2:0] SP;


    always @(posedge Clk) begin
        if (EN) begin
            if (Rst) begin

                integer i;
                for (i = 0;
 i < 4;
 i = i + 1)
                    stack_mem[i] <= 4'b0;
                SP <= 4;
            end else begin
                if (RW) begin 
                    if (!FULL) begin
                        dataOut <= stack_mem[SP];
                        stack_mem[SP] <= 4'b0;

                        SP <= SP + 1;

                    end
                end else begin 
                    if (!EMPTY) begin
                        stack_mem[SP-1] <= dataIn;

                        SP <= SP - 1;

                    end
                end
            end
        end
    end


    always @(*) begin
        EMPTY = (SP == 4);
        FULL = (SP == 0);
    end

endmodule

