module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg state_reg;
localparam IDLE = 1'b0;
localparam DETECT = 1'b1;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state_reg <= IDLE;
        data_out <= 1'b0;
    end else begin
        case (state_reg)
            IDLE: begin
                if (data_in) begin
                    state_reg <= DETECT;
                end else begin
                    state_reg <= IDLE;
                end
                data_out <= 1'b0;
            end
            DETECT: begin
                if (~data_in) begin
                    state_reg <= IDLE;
                    data_out <= 1'b1;
                end else begin
                    state_reg <= DETECT;
                    data_out <= 1'b0;
                end
            end
            default: begin
                state_reg <= IDLE;
                data_out <= 1'b0;
            end
        endcase
    end
end

endmodule

