    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);
    parameter [1:0] idle = 2'd0, s1_red = 2'd1, s2_yellow = 2'd2, s3_green = 2'd3;

