                    p_red <= 0;
                    p_yellow <= 1;
                    p_green <= 0;
                end
                s3_green: begin
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 1;
                end
                default: begin
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
            endcase
        end
    end

endmodule

