module alu (a, b, aluc, r, zero, carry, negative, overflow, flag);
input [31:0] a, b;
input [5:0] aluc;
output reg [31:0] r;
output zero, negative, flag;
output reg carry, overflow;
wire [31:0] res;



always @(*) begin
    case (aluc)
        ADD: begin

            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
        end
        ADDU: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = 0;
        end
        SUB: begin

            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
        end
        SUBU: begin
            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = 0;
        end
        AND: begin
            r = a & b;
            carry = 0;
            overflow = 0;
        end
        OR: begin
            r = a | b;
            carry = 0;
            overflow = 0;
        end
        XOR: begin
            r = a ^ b;
            carry = 0;
            overflow = 0;
        end
        NOR: begin
            r = ~(a | b);
            carry = 0;
            overflow = 0;
        end
        SLT: begin
            r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;


        end
        SLTU: begin
            r = (a < b) ? 32'd1 : 32'd0;

        end
        SLL: begin
            r = b << a[4:0];
            carry = 0;
            overflow = 0;
        end
        SRL: begin
            r = b >> a[4:0];
            carry = 0;
            overflow = 0;
        end
        SRA: begin
            r = $signed(b) >>> a[4:0];
            carry = 0;
            overflow = 0;
        end
        SLLV: begin
            r = b << a[4:0];
            carry = 0;
            overflow = 0;
        end
        SRLV: begin
            r = b >> a[4:0];
            carry = 0;
            overflow = 0;
        end
        SRAV: begin
            r = $signed(b) >>> a[4:0];
            carry = 0;
            overflow = 0;
        end
        LUI: begin
            r = {a[15:0], 16'b0};

        end
        default: begin
            r = 32'bz;
            carry = 0;
            overflow = 0;
        end
    endcase
end


assign zero = (r == 32'b0);
assign negative = r[31];


reg flag_reg;
always @(*) begin
    case (aluc)
        SLT: flag_reg = ($signed(a) < $signed(b)) ? 1'b1 : 1'b0;
        SLTU: flag_reg = (a < b) ? 1'b1 : 1'b0;
        default: flag_reg = 1'bz;
    endcase
end
assign flag = (aluc == SLT || aluc == SLTU) ? flag_reg : 1'bz;

endmodule

