    output clk_div;

    reg [2:0] counter;
    reg clk_a, clk_a_shift;
    reg clk_b, clk_b_shift;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            counter <= 3'b0;
        else
            counter <= (counter == 3'd6) ? 3'b0 : counter + 3'd1;
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            clk_a <= 1'b0;
        else begin
            if (counter == 3'd1 || counter == 3'd3 || counter == 3'd5)
                clk_a <= ~clk_a;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            clk_b <= 1'b0;
        else begin
            if (counter == 3'd1 || counter == 3'd4)
                clk_b <= ~clk_b;
        end
    end


    always @(negedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_a_shift <= 1'b0;
            clk_b_shift <= 1'b0;
        end else begin
            clk_a_shift <= clk_a;
            clk_b_shift <= clk_b;
        end
    end


    assign clk_div = clk_a | clk_a_shift | clk_b | clk_b_shift;
endmodule

