module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg [8:0] NEG_DIVISOR;
reg original_dividend_sign;
reg original_divisor_sign;
reg [16:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg div_state;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        result <= 16'b0;
        div_state <= 0;
        start_cnt <= 0;
        cnt <= 0;
        SR <= 17'b0;
        abs_dividend <= 8'b0;
        abs_divisor <= 8'b0;
        NEG_DIVISOR <= 9'b0;
        original_dividend_sign <= 0;
        original_divisor_sign <= 0;
    end else begin
        if (!div_state) begin
            if (opn_valid && !res_valid) begin
                original_dividend_sign <= sign && dividend[7];
                original_divisor_sign <= sign && divisor[7];
                if (sign) begin
                    abs_dividend <= (dividend[7]) ? -dividend : dividend;
                    abs_divisor <= (divisor[7]) ? -divisor : divisor;
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                end
                SR <= { (abs_dividend << 1), 8'b0 };
                NEG_DIVISOR <= {1'b0, -abs_divisor};
                start_cnt <= 1;
                cnt <= 1;
                div_state <= 1;
            end
        end else begin
            if (start_cnt) begin
                if (cnt < 8) begin
                    reg [8:0] remainder = SR[16:8];
                    reg [8:0] divisor_9bit = {1'b0, abs_divisor};
                    reg [8:0] remainder_minus_divisor = remainder - divisor_9bit;
                    reg carry_out = (remainder >= divisor_9bit);
                    SR[16:8] <= (remainder << 1) | SR[7];
                    SR[7:0] <= (SR[7:0] << 1) | carry_out;
                    cnt <= cnt + 1;
                end else begin
                    start_cnt <= 0;
                    div_state <= 0;
                    reg [7:0] final_quotient = SR[7:0];
                    reg [7:0] final_remainder = SR[16:9];
                    if (sign) begin
                        if (original_divisor_sign != original_dividend_sign)
                            final_quotient = -final_quotient;
                        if (original_dividend_sign)
                            final_remainder = -final_remainder;
                    end
                    result <= {final_remainder, final_quotient};
                    res_valid <= 1;
                end
            end
            if (opn_valid && res_valid) begin
                res_valid <= 0;
            end
        end
    end
end

endmodule

