module div_16bit(A, B, result, odd);
    input [15:0] A, B;
    output reg [15:0] result, odd;
    reg [15:0] a_reg, b_reg;


    always @(A, B) begin
        a_reg = A;
        b_reg = B;
    end


    always @(A, B) begin
        reg [15:0] rem = {a_reg[15:8], 8'b0};

        reg [15:0] quotient = 16'b0;
        reg [7:0] divisor = b_reg;
        integer i;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            if (rem >= divisor) begin
                quotient[i] = 1'b1;
                rem = rem - divisor;
            end else begin
                quotient[i] = 1'b0;
            end




        end

        result = quotient;
        odd = rem;
    end
endmodule

