            if (valid_in) begin

                accumulator <= accumulator + data_in;
                count <= count + 1;
            end

            if (valid_in && (count + 1) == 4) begin
                data_out <= accumulator + data_in;

                valid_out <= 1'b1;
                count <= 2'b00;
                accumulator <= 10'b0;
            end
        end
    end
endmodule

