module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output reg wfull,
    output reg rempty,
    output wire [WIDTH-1:0] rdata
);
    reg [3:0] waddr_bin, raddr_bin;
    reg [3:0] wptr, rptr;
    reg [3:0] rptr_syn1, rptr_syn;
    reg [3:0] wptr_syn1, wptr_syn;
    wire wenc, renc;
    wire [3:0] waddr, raddr;


    dual_port_RAM #(.WIDTH(WIDTH), .DEPTH(DEPTH)) ram (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(raddr),
        .rdata(rdata)
    );


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            waddr_bin <= 0;
        else if (winc && !wfull)
            waddr_bin <= waddr_bin + 1;
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            raddr_bin <= 0;
        else if (rinc && !rempty)
            raddr_bin <= raddr_bin + 1;
    end


    function [3:0] bin2gray(input [3:0] bin);
        bin2gray = bin ^ (bin >> 1);
    endfunction

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            wptr <= 0;
        else
            wptr <= bin2gray(waddr_bin);
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            rptr <= 0;
        else
            rptr <= bin2gray(raddr_bin);
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_syn1 <= 0;
            rptr_syn <= 0;
        end else begin
            rptr_syn1 <= rptr;
            rptr_syn <= rptr_syn1;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_syn1 <= 0;
            wptr_syn <= 0;
        end else begin
            wptr_syn1 <= wptr;
            wptr_syn <= wptr_syn1;
        end
    end


    assign wenc = winc && !wfull;
    assign renc = rinc && !rempty;


    assign waddr = waddr_bin;
    assign raddr = raddr_bin;


    always @(*) begin
        wfull = (wptr == {~rptr_syn[3], ~rptr_syn[2], rptr_syn[1:0]});
        rempty = (rptr == wptr_syn);
    end

endmodule


