module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);
    reg [3:0] stack_mem [0:3];

    reg [2:0] SP;


    always @(posedge Clk) begin
        if (EN) begin
            if (Rst) begin 
                SP <= 3'b100;

                EMPTY <= 1'b1;
                FULL <= 1'b0;
                stack_mem[0] <= 4'b0;
                stack_mem[1] <= 4'b0;
                stack_mem[2] <= 4'b0;
                stack_mem[3] <= 4'b0;
            end else begin

                FULL <= (SP == 3'b100);

                EMPTY <= (SP == 3'b100);



                if (SP == 3'b100) begin
                    EMPTY <= 1'b1;
                    FULL <= 1'b0;
                end else begin
                    EMPTY <= (SP == 0);
                    FULL <= (SP == 0);
                end

                if (RW) begin 
                    if (!EMPTY) begin
                        dataOut <= stack_mem[SP];
                        stack_mem[SP] <= 4'b0;
                        SP <= SP + 1;

                    end
                end else begin 
                    if (!FULL) begin
                        stack_mem[SP] <= dataIn;
                        SP <= SP - 1;

                    end
                end
            end
        end
    end
endmodule

