            a_phase_shifted <= 1'b0;
            b_phase_shifted <= 1'b0;
        end else begin
            a_phase_shifted <= a;

            b_phase_shifted <= (counter[0]) ? b : ~b;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (~rst_n)
            clk_div <= 1'b0;
