module cla_4bit(A, B, C_in, S, G, P, C_out);
    input [4:1] A, B;
    input C_in;
    output [4:1] S;
    output G, P, C_out;

    wire g0, p0, g1, p1, g2, p2, g3, p3;
    wire c1, c2, c3;

    assign g0 = A[1] & B[1];
    assign p0 = A[1] | B[1];
    assign g1 = A[2] & B[2];
    assign p1 = A[2] | B[2];
    assign g2 = A[3] & B[3];
    assign p2 = A[3] | B[3];
    assign g3 = A[4] & B[4];
    assign p3 = A[4] | B[4];

    assign G = g3 | (p3 & g2) | (p3 & p2 & g1) | (p3 & p2 & p1 & g0);
    assign P = p3 & p2 & p1 & p0;

    assign C_out = G | (P & C_in);

    assign c1 = g0 | (p0 & C_in);
    assign c2 = g1 | (p1 & g0) | (p1 & p0 & C_in);
    assign c3 = g2 | (p2 & g1) | (p2 & p1 & g0) | (p2 & p1 & p0 & C_in);

    assign S[1] = A[1] ^ B[1] ^ C_in;
    assign S[2] = A[2] ^ B[2] ^ c1;
    assign S[3] = A[3] ^ B[3] ^ c2;
    assign S[4] = A[4] ^ B[4] ^ c3;
