module fixed_point_adder #(parameter Q=16, parameter N=32) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    wire msb_a = a[N-1];
    wire msb_b = b[N-1];
    wire same_sign = (msb_a == msb_b);
    wire [N-1:0] abs_a, abs_b;
    wire [N-1:0] a_plus_b, a_sub_b, b_sub_a;


    assign abs_a = msb_a ? (~a + 1) : a;
    assign abs_b = msb_b ? (~b + 1) : b;


    assign a_plus_b = a + b;
    assign a_sub_b = a - b;
    assign b_sub_a = b - a;

    always @* begin
        if (same_sign) begin

            res = a_plus_b;
        end else begin

            if (abs_a > abs_b)
                res = a_sub_b;
            else if (abs_a < abs_b)
                res = b_sub_a;
            else
                res = 0;
        end
    end

    assign c = res;
endmodule

