                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hFF;
                            z_mantissa <= {1'b0, a_mantissa[22:0]} | {23{1'b1}};
                        end else begin

                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hFF;
                            z_mantissa <= 24'd0;
                        end
                        counter <= 4;
                    end

                    else if (a_mantissa[22:0] == 23'd0 && b_mantissa[22:0] == 23'd0) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 8'd0;
                        z_mantissa <= 24'd0;
                        counter <= 4;
                    end

                    else begin
                        product <= a_mantissa * b_mantissa;
                        counter <= counter + 1;
                    end
                end


                3'd2: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 8'd127 + 8'd1;
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                    end
                    counter <= counter + 1;
                end


                3'd3: begin

                    if (product[47]) begin 
                        guard_bit <= product[46];
