    case (state)
        IDLE: next_state = data_in ? S1 : IDLE;
        S1:   next_state = data_in ? S1 : S2;
        S2:   next_state = data_in ? S1 : S3;
        S3:   next_state = data_in ? S4 : IDLE;
        S4:   next_state = data_in ? S1 : IDLE;
        default: next_state = IDLE;
    endcase
end


always @(*) begin
    sequence_detected = (state == S4);
end

