module traffic_light (
    input  wire       rst_n,
    input  wire       clk,
    input  wire       pass_request,
    output reg [7:0]  clock,
    output reg        red,
    output reg        yellow,
    output reg        green
);

    parameter idle     = 2'b00;
    parameter s1_red   = 2'b01;
    parameter s3_green = 2'b10;
    parameter s2_yellow= 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg p_red_prev, p_yellow_prev, p_green_prev;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 10;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            state <= next_state;
            case (state)
                idle: begin
                    p_red <= 1;
                    p_yellow <= 0;
                    p_green <= 0;
                end
                s1_red: begin
                    if (cnt == 3) begin
                        p_red <= 0;
                        p_yellow <= 0;
                        p_green <= 1;
                    end
                end
                s3_green: begin
                    if (cnt == 3) begin
                        p_green <= 0;
                        p_yellow <= 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 3) begin
                        p_yellow <= 0;
                        p_red <= 1;
                    end
                end
            endcase


            p_red_prev <= p_red;
            p_yellow_prev <= p_yellow;
            p_green_prev <= p_green;


            if (pass_request && p_green) begin
                cnt <= 10;
            end else if (!p_green && p_green_prev) begin
                cnt <= 60;
            end else if (!p_yellow && p_yellow_prev) begin
                cnt <= 5;
            end else if (!p_red && p_red_prev) begin
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(*) begin
        case (state)
            idle:     next_state = s1_red;
            s1_red:   next_state = (cnt == 3) ? s3_green : s1_red;
            s3_green: next_state = (cnt == 3) ? s2_yellow : s3_green;
            s2_yellow: next_state = (cnt == 3) ? s1_red : s2_yellow;
            default:  next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end


    always @(posedge clk) begin
        clock <= cnt;
    end

endmodule

