    reg [15:0] remainder;
    reg [15:0] quotient;
    integer i;

    remainder = 16'b0;
    quotient = 16'b0;
    for (i = 15;
 i >= 0;
 i = i - 1) begin
        remainder = {remainder[14:0], a_reg[i]};
