    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output reg [31:0] yout,
    output reg done
);
    reg [15:0] areg, breg;
    reg [4:0] i;
    reg [31:0] yout_r;
    reg done_r;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            areg <= 16'b0;
            breg <= 16'b0;
            yout_r <= 32'b0;
            i <= 5'b0;
            done_r <= 1'b0;
        end else begin
            reg [4:0] next_i;
            next_i = i;
            if (start) begin
                if (i < 17)
                    next_i = i + 1;
            end else begin
                next_i = 5'b0;
            end


            if (next_i == 16)
                done_r <= 1'b1;
            else if (next_i == 17)
                done_r <= 1'b0;

            i <= next_i;


            if (start) begin
                if (i == 0) begin
                    areg <= ain;
                    breg <= bin;
                end else if (i > 0 && i < 17) begin
                    if (areg[i-1])
                        yout_r <= yout_r + (breg << (i-1));
                end
            end
        end
    end

    assign yout = yout_r;
    assign done = done_r;

endmodule

