module fixed_point_adder #(parameter Q, parameter N) (a, b, c);
    input [N-1:0] a, b;
    output [N-1:0] c;
    reg [N-1:0] res;
    wire a_msb, b_msb;
    wire [N-1:0] absolute_a, absolute_b;

    assign a_msb = a[N-1];
    assign b_msb = b[N-1];

    always @(*) begin
        if (a_msb == b_msb) begin
            res = a + b;
            res[N-1] = a_msb;
        end else begin

            absolute_a = a_msb ? (-a) : a;
            absolute_b = b_msb ? (-b) : b;


            if ($unsigned(absolute_a) > $unsigned(absolute_b)) begin
                res = absolute_a - absolute_b;
                res[N-1] = 1'b0;
            end else begin
                res = absolute_b - absolute_a;
                res[N-1] = 1'b1;
            end
        end
    end

    assign c = res;

endmodule

