module fixed_point_subtractor #(parameter Q, parameter N) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg sign_a, sign_b;
    reg [N-1:0] same_sign_res;
    reg [N-1:0] diff_sign_res;
    reg [N-1:0] res_temp;
    reg sign_res;

    wire [N-1:0] abs_a, abs_b;


    assign abs_a = sign_a ? (~a + 1) : a;
    assign abs_b = sign_b ? (~b + 1) : b;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        res = c;



        if (sign_a == sign_b) begin
            same_sign_res = a - b;
            sign_res = sign_a;
            res_temp = {sign_res, same_sign_res[N-2:0]};

        end

        else begin
            diff_sign_res = abs_a + abs_b;
            if (abs_a > abs_b)
                sign_res = ~sign_a;
            else
                sign_res = ~sign_b;
            res_temp = {sign_res, diff_sign_res[N-2:0]};
        end


        if (res_temp == 0)
            res = {1'b0, {N-1{1'b0}}};
        else
            res = res_temp;

        c = res;
    end
endmodule

