    function [PTR_WIDTH-1:0] bin2gray(input [PTR_WIDTH-1:0] bin);
        bin2gray = bin ^ (bin >> 1);
    endfunction


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            wenc <= 0;
        end else begin
            wenc <= winc && !wfull;
            if (wenc)
                waddr_bin <= waddr_bin + 1;
        end
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_gray <= 0;
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            wptr_gray <= bin2gray(waddr_bin);
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            renc <= 0;
        end else begin
            renc <= rinc && !rempty;
            if (renc)
                raddr_bin <= raddr_bin + 1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_gray <= 0;
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            rptr_gray <= bin2gray(raddr_bin);
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end


    function [PTR_WIDTH-1:0] gray2bin(input [PTR_WIDTH-1:0] gray);
        gray2bin = gray ^ (gray >> 1) ^ (gray >> 2) ^ (gray >> 3);
    endfunction

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            wptr_bin_syn <= 0;
        else
            wptr_bin_syn <= gray2bin(wptr_gray_sync2);
    end

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            rptr_bin_syn <= 0;
        else
            rptr_bin_syn <= gray2bin(rptr_gray_sync2);
    end


    assign rempty = (wptr_gray == rptr_gray);
    assign wfull = (wptr_gray == {~rptr_gray_sync[ADDR_WIDTH], ~rptr_gray_sync[ADDR_WIDTH-1], rptr_gray_sync[ADDR_WIDTH-2:0]});

endmodule


