module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg [3:0] dout
);
reg [1:0] cnt;
reg [3:0] data;

always @(posedge clk) begin
    if (~rst_n) begin
        cnt <= 2'b00;
        data <= 4'b0000;
        valid_out <= 1'b0;
        dout <= 4'b0000;
    end else begin
        if (cnt == 2'd3) begin
            data <= d;
            cnt <= 2'd0;
            valid_out <= 1'b1;
            dout <= d[3];
        end else begin
            data <= data << 1;
            dout <= (data << 1)[3];
            cnt <= cnt + 1;
            valid_out <= 1'b0;
        end
    end
end

endmodule

