module alu(a, b, aluc, r, zero, carry, negative, overflow, flag);
input [31:0] a, b;
input [5:0] aluc;
output reg [31:0] r;
output zero, carry, negative, overflow, flag;

parameter ADD = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND = 6'b100100;
parameter OR = 6'b100101;
parameter XOR = 6'b100110;
parameter NOR = 6'b100111;
parameter SLT = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL = 6'b000000;
parameter SRL = 6'b000010;
parameter SRA = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI = 6'b001111;

reg [31:0] res;
reg carry_reg, overflow_reg;

assign r = res;
assign zero = (res == 32'b0);
assign negative = res[31];
assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

always @(*) begin
    case (aluc)
        ADD: begin
            {carry_reg, res} = {1'b0, a} + {1'b0, b};
            overflow_reg = (a[31] == b[31]) && (res[31] != a[31]);
        end
        ADDU: begin
            res = a + b;
            carry_reg = 1'b0;

            overflow_reg = 1'b0;
        end
        SUB: begin
            {carry_reg, res} = {1'b0, a} - {1'b0, b};
            carry_reg = ~carry_reg;

            overflow_reg = (a[31] != b[31]) && (res[31] != a[31]);
        end
        SUBU: begin
            res = a - b;
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        AND: begin
            res = a & b;
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        OR: begin
            res = a | b;
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        XOR: begin
            res = a ^ b;
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        NOR: begin
            res = ~(a | b);
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SLT: begin
            res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SLTU: begin
            res = (a < b) ? 32'd1 : 32'd0;
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SLL: begin
            res = b << a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SRL: begin
            res = b >> a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SRA: begin
            res = $signed(b) >>> a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SLLV: begin
            res = b << a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SRLV: begin
            res = b >> a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SRAV: begin
            res = $signed(b) >>> a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        LUI: begin
            res = {a[31:16], 16'b0};
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        default: begin
            res = 32'bz;
            carry_reg = 1'bz;
            overflow_reg = 1'bz;
        end
    endcase
end

assign carry = carry_reg;
assign overflow = overflow_reg;

endmodule

