module div_16bit(A, B, result, odd);
input [15:0] A, B;
output reg [15:0] result, odd;

reg [15:0] a_reg, b_reg;


always @(A, B) begin
    a_reg = A;
    b_reg = B;
end


always @(A, B) begin
    result = 16'b0;
    odd = 16'b0;


    if (a_reg[15:8] >= b_reg) begin
        result[0] = 1'b1;
        odd[15:8] = a_reg[15:8] - b_reg;
        odd[7:0] = a_reg[7:0];
        a_reg = {a_reg[15:8] - b_reg, a_reg[7:0]};

    end else begin
        result[0] = 1'b0;
        odd[15:8] = a_reg[15:8];
        odd[7:0] = a_reg[7:0];
    end


    if (a_reg[15:8] >= b_reg) begin
        result[1] = 1'b1;
        odd[15:8] = a_reg[15:8] - b_reg;
        a_reg = {a_reg[15:8] - b_reg, a_reg[7:0]};

    end else begin
        result[1] = 1'b0;
        odd[15:8] = a_reg[15:8];
    end


    odd[7:0] = a_reg[7:0];
end

