module fixed_point_adder #(parameter Q=4, N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire [N-2:0] a_mag = a[N-2:0];
    wire [N-2:0] b_mag = b[N-2:0];

    always @(*) begin
        if (a_sign == b_sign) begin

            res[N-1] = a_sign;
            res[N-2:0] = a_mag + b_mag;
        end else begin

            if (a_mag > b_mag) begin
                res[N-1] = a_sign;
                res[N-2:0] = a_mag - b_mag;
            end else if (b_mag > a_mag) begin
                res[N-1] = b_sign;
                res[N-2:0] = b_mag - a_mag;
            end else begin
                res[N-1] = 1'b0;
                res[N-2:0] = {(N-1){1'b0}};
            end
        end
        c = res;
    end
