module fixed_point_subtractor #(parameter Q=4, N=8) (
    input [N-1:0] a, b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    always @* begin
        if (a[N-1] == b[N-1]) begin

            res = a - b;
            res[N-1] = a[N-1];
        end else begin

            if (a[N-1] == 0) begin 
                if (a >= -b) begin
                    res = a - b;
                    res[N-1] = 0;
                end else begin
                    res = -b - a;
                    res[N-1] = 1;
                end
            end else begin 
                if (-a >= b) begin
                    res = a - b;
                    res[N-1] = 0;
                end else begin
                    res = -b - a;
                    res[N-1] = 1;
                end
            end
        end

        if (res == 0)
            res[N-1] = 0;
        c = res;
    end
endmodule

