module float_multi (
    input wire clk,
    input wire rst,
    input wire [31:0] a,
    input wire [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;

    reg [47:0] product;
    reg guard, round, sticky;
    reg overflow, underflow;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b000;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            z_exponent <= 0;
            a_mantissa <= 24'b0;
            b_mantissa <= 24'b0;
            product <= 48'b0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            overflow <= 0;
            underflow <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};

                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= 3'b001;
                end
                3'b001: begin

                    if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                        if (a_exponent == 8'hff && b_exponent == 8'hff) begin

                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hff;
                            z <= {a_sign, 8'hff, 1'b1, a[22:0]};
                        end else begin

                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hff;
                            z <= {a_sign, 8'hff, 1'b1, a[22:0]};
                        end
                    end else if (a_exponent == 0 || b_exponent == 0) begin

                        if (a_exponent == 0 && a_mantissa == 0 && b_exponent == 0 && b_mantissa == 0) begin

                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 0;
                            z <= {a_sign ^ b_sign, 31'b0};
                        end else begin



                            product <= a_mantissa * b_mantissa;
                        end
                    end else begin

                        product <= a_mantissa * b_mantissa;
                    end
                    counter <= 3'b010;
                end
                3'b010: begin


                    integer i;
                    reg [47:0] normalized_product;
                    reg [9:0] exp;
                    reg leading_one;
                    leading_one = 0;
                    normalized_product = product;
                    exp = a_exponent + b_exponent - 8'd127;

                    for (i = 47;
 i >= 0;
 i = i - 1) begin
                        if (normalized_product[i]) begin
                            leading_one = 1;
                            normalized_product = normalized_product << (47 - i);
                            exp = exp - (47 - i);
                            break;
                        end
                    end
                    if (!leading_one) begin

                        z <= {z_sign, 31'b0};
                    end else begin
                        z_mantissa = normalized_product[46:24];



                        if (normalized_product[23] && (normalized_product[22] || sticky)) begin
                            z_mantissa = z_mantissa + 1;
                            if (z_mantissa[23]) begin

                                z_mantissa = 23'b0;
                                exp = exp + 1;
                            end
                        end

                        if (exp > 8'd254) begin

                            z <= {z_sign, 8'hff, 23'b0};
                        end else if (exp < 9'd1) begin


                            z <= {z_sign, 31'b0};
                        end else begin
                            z_exponent <= exp;
                            z <= {z_sign, exp[7:0], z_mantissa};
                        end
                    end
                    counter <= 3'b111;
                end
                3'b111: begin
                    counter <= 3'b000;
                end
                default: begin
                    counter <= counter + 1;
                end
            endcase
        end
    end

