module LIFObuffer (
    input [3:0] dataIn,
    input RW, EN, Rst, Clk,
    output EMPTY, FULL,
    output reg [3:0] dataOut
);
    reg [3:0] stack_mem [0:3];
    reg [2:0] SP;

    reg [3:0] dataOut_reg;
    reg EMPTY_reg, FULL_reg;

    always @(posedge Clk) begin
        if (EN) begin
            if (Rst) begin
                SP <= 4;
                stack_mem[0] <= 0;
                stack_mem[1] <= 0;
                stack_mem[2] <= 0;
                stack_mem[3] <= 0;
                dataOut_reg <= 0;
            end else begin
                if (RW) begin 
                    if (!EMPTY_reg) begin
                        dataOut_reg <= stack_mem[SP];
                        SP <= SP + 1;
                    end
                end else begin 
                    if (!FULL_reg) begin
                        stack_mem[SP-1] <= dataIn;
                        SP <= SP - 1;
                    end
                end
            end
        end
    end

    always @(*) begin
        EMPTY_reg = (SP == 4);
        FULL_reg = (SP == 0);
    end

    assign EMPTY = EMPTY_reg;
    assign FULL = FULL_reg;
    assign dataOut = dataOut_reg;

