module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    reg [1:0] state;

    localparam IDLE = 2'b00;
    localparam S1 = 2'b01;
    localparam S2 = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            data_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    data_out <= 0;
                    if (data_in) begin
                        state <= S1;
                    end else begin
                        state <= IDLE;
                    end
                end
                S1: begin
                    data_out <= 0;
                    if (data_in) begin
                        state <= IDLE;
                    end else begin
                        state <= S2;
                    end
                end
                S2: begin
                    if (data_in) begin
                        state <= IDLE;
                        data_out <= 0;
                    end else begin
                        state <= IDLE;
                        data_out <= 1;
                    end
                end
                default: begin
                    state <= IDLE;
                    data_out <= 0;
                end
            endcase
        end
    end

endmodule

