module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output reg flag
);
    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] a_signed, b_signed;
    reg [31:0] a_unsigned, b_unsigned;
    reg [31:0] res;

    always @(*) begin
        a_signed = $signed(a);
        b_signed = $signed(b);
        a_unsigned = a;
        b_unsigned = b;
    end

    assign zero = (r == 32'b0);
    assign negative = r[31];

    always @(*) begin
        if (aluc == SLT)
            flag = (a_signed < b_signed);
        else if (aluc == SLTU)
            flag = (a_unsigned < b_unsigned);
        else
            flag = 1'bz;
    end

    always @(*) begin
        res = 32'bz;
        carry = 0;
        overflow = 0;
        case (aluc)
            ADD: begin
                {carry, res} = {1'b0, a} + {1'b0, b};
                overflow = (a_signed[31] & b_signed[31] & ~res[31]) | (~a_signed[31] & ~b_signed[31] & res[31]);
            end
            ADDU: begin
                {carry, res} = {1'b0, a} + {1'b0, b};
                overflow = 0;
            end
            SUB: begin
                {carry, res} = {1'b0, a} - {1'b0, b};
                overflow = (a_signed[31] & ~b_signed[31] & ~res[31]) | (~a_signed[31] & b_signed[31] & res[31]);
            end
            SUBU: begin
                {carry, res} = {1'b0, a} - {1'b0, b};
                overflow = 0;
            end
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: res = (a_signed < b_signed) ? 32'd1 : 32'd0;
            SLTU: res = (a_unsigned < b_unsigned) ? 32'd1 : 32'd0;
            SLL: res = b << a[4:0];
            SRL: res = b >> a[4:0];
            SRA: res = $signed(b) >>> a[4:0];
            SLLV: res = b << a[4:0];
            SRLV: res = b >> a[4:0];
            SRAV: res = $signed(b) >>> a[4:0];
            LUI: res = {a[31:16], 16'b0};
            default: res = 32'bz;
        endcase
    end

    assign r = res;

endmodule

