module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] stored_dividend, stored_divisor;
    reg [7:0] abs_dividend, abs_divisor;
    reg [15:0] sr;

    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] remainder;
    reg [7:0] quotient;
    reg sign_dividend, sign_divisor;
    reg [8:0] neg_divisor;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            sr <= 16'b0;
            cnt <= 4'b0;
            start_cnt <= 0;
            stored_dividend <= 8'b0;
            stored_divisor <= 8'b0;
            abs_dividend <= 8'b0;
            abs_divisor <= 8'b0;
            remainder <= 8'b0;
            quotient <= 8'b0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            neg_divisor <= 9'b0;
        end else begin
            if (opn_valid && !res_valid) begin

                stored_dividend <= dividend;
                stored_divisor <= divisor;
                sign_dividend <= sign ? dividend[7] : 0;
                sign_divisor <= sign ? divisor[7] : 0;
                abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;

                sr <= {abs_dividend[7:0], 1'b0} << 1;
                neg_divisor <= -abs_divisor;
                cnt <= 4'd1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt < 4'd8) begin

                    if (sr[15:8] >= neg_divisor) begin
                        sr[15:8] <= sr[15:8] - neg_divisor;
                        sr[7:0] <= {sr[6:0], 1'b1};
                    end else begin
                        sr[7:0] <= {sr[6:0], 1'b0};
                    end
                    sr <= {sr[14:0], 1'b0};

                    cnt <= cnt + 1;
                end else begin

                    remainder <= sr[15:8];
                    quotient <= sr[7:0];
                    start_cnt <= 0;
                end
            end
            if (start_cnt == 0 && cnt == 4'd8) begin

                if (sign) begin
                    quotient <= (sign_dividend ^ sign_divisor) ? -quotient : quotient;
                    remainder <= (sign_dividend) ? -remainder : remainder;
                end
                result <= {remainder, quotient};
                res_valid <= 1;
            end
        end
    end
endmodule

