module div_16bit(A, B, result, odd);
  input [15:0] A;
  input [7:0] B;
  output reg [15:0] result;
  output reg [15:0] odd;

  reg [15:0] a_reg, b_reg;
  reg [15:0] remainder;
  integer i;


  always @(*) begin
    a_reg = A;
    b_reg = B;
  end


  always @(*) begin
    remainder = 16'b0;
    result = 16'b0;
    for (i = 15;
 i >= 0;
 i = i - 1) begin
      remainder = (remainder << 1) | (a_reg[i] ? 1'b1 : 1'b0);
      if (remainder >= b_reg) begin
        result[i] = 1'b1;
        remainder = remainder - b_reg;
      end else begin
        result[i] = 1'b0;
      end
    end
    odd = remainder;
  end
endmodule

