        if (~rst_n) begin
            sum_reg <= 10'b0;
            count_reg <= 2'b00;
            data_out <= 10'b0;
            valid_out <= 1'b0;
        end else begin
            valid_out <= 1'b0;

            if (valid_in) begin
                sum_reg <= sum_reg + data_in;
                count_reg <= count_reg + 1'b1;
                if (count_reg == 2'b11) begin 
                    data_out <= sum_reg + data_in;
                    valid_out <= 1'b1;
                end
            end
        end
    end
endmodule

