module fixed_point_adder #(parameter Q=3, parameter N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg sign_a, sign_b;
    reg [N-1:0] mag_a, mag_b;
    reg [N:0] sum_mag;

    reg [N-1:0] res_mag;
    reg expected_sign;
    integer max_mag;

    always @* begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        mag_a = sign_a ? (~a + 1) : a;
        mag_b = sign_b ? (~b + 1) : b;

        if (sign_a == sign_b) begin

            sum_mag = mag_a + mag_b;
            if (sum_mag > ( (1 << (N-1)) - 1 )) begin

                res = {sign_a, {N-1{1'b1}}};
            end else begin
                res = {sign_a, sum_mag[N-2:0]};
            end
        end else begin

            if (mag_a > mag_b) begin
                res_mag = mag_a - mag_b;
                expected_sign = sign_a;
            end else if (mag_b > mag_a) begin
                res_mag = mag_b - mag_a;
                expected_sign = sign_b;
            end else begin
                res_mag = 0;
                expected_sign = 1'b0;
            end
            res = {expected_sign, res_mag[N-2:0]};
        end
        c = res;
    end

endmodule

