module float_multi (
    input wire clk,
    input wire rst,
    input wire [31:0] a,
    input wire [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [8:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [48:0] product;
    reg guard_bit, round_bit, sticky_bit;
    reg [23:0] a_mantissa_full, b_mantissa_full;
    reg [23:0] product_normal;
    reg [22:0] z_mantissa;
    reg [9:0] z_exponent_tmp;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)

                3'b000: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    counter <= 3'b001;
                end

                3'b001: begin

                    if ((a_exponent == 9'h1FF) || (b_exponent == 9'h1FF)) begin
                        if ((a_exponent == 9'h1FF) && (b_exponent == 9'h1FF)) begin
                            z_sign <= a_sign ^ b_sign;
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h1};
                        end else begin
                            z_sign <= (a_exponent == 9'h1FF) ? a_sign : b_sign;
                            z <= {(a_exponent == 9'h1FF) ? a_sign : b_sign, 8'hFF, (a_exponent == 9'h1FF) ? 23'h1 : 23'h0};
                        end
                    end else if (a_exponent == 9'h0) begin
                        z_sign <= (b_exponent == 9'h0 && b_mantissa == 23'b0) ? 1'b0 : a_sign ^ b_sign;
                        z <= 32'b0;
                    end else if (b_exponent == 9'h0) begin
                        z_sign <= (a_exponent == 9'h0 && a_mantissa == 23'b0) ? 1'b0 : a_sign ^ b_sign;
                        z <= 32'b0;
                    end else begin
                        counter <= 3'b010;
                    end
                end

                3'b010: begin
                    a_mantissa_full <= (a_exponent != 9'h0) ? {1'b1, a_mantissa} : {1'b0, a_mantissa};
                    b_mantissa_full <= (b_exponent != 9'h0) ? {1'b1, b_mantissa} : {1'b0, b_mantissa};
                    product <= a_mantissa_full * b_mantissa_full;
                    z_exponent_tmp <= (a_exponent - 9'h7F) + (b_exponent - 9'h7F);
                    counter <= 3'b011;
                end

                3'b011: begin

                    if (product[47]) begin
                        product_normal <= product >> 1;
                        z_exponent_tmp <= z_exponent_tmp + 1;
                    end else begin
                        product_normal <= product[46:0];
                    end

                    guard_bit <= product_normal[23];
                    round_bit <= product_normal[22];
                    sticky_bit <= |product_normal[21:0];

                    if (guard_bit) begin
                        if (round_bit || sticky_bit) begin
                            product_normal[22:0] <= product_normal[22:0] + 1;
                        end else if (product_normal[22]) begin
                            product_normal[22:0] <= product_normal[22:0] + 1;
                        end
                    end

                    if (product_normal[22] && (product_normal[21:0] >= 22'h100000)) begin
                        product_normal[22:0] <= product_normal[22:0] >> 1;
                        z_exponent_tmp <= z_exponent_tmp + 1;
                    end

                    z_sign <= a_sign ^ b_sign;
                    if (z_exponent_tmp > 9'h1FE) begin
                        z <= {z_sign, 8'hFF, 23'b0};
                    end else if (z_exponent_tmp < 9'h1) begin
                        z <= {z_sign, 31'b0};
                    end else begin
                        z <= {z_sign, z_exponent_tmp[7:0], product_normal[22:1]};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end
endmodule

