module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);
    reg [3:0] stack_mem [0:3];
    reg [2:0] SP;


    always @(posedge Clk) begin
        if (EN) begin
            if (Rst) begin

                SP <= 3'd4;
                EMPTY <= 1'b1;
                FULL <= 1'b0;
                for (integer i = 0;
 i < 4;
 i = i + 1)
                    stack_mem[i] <= 4'b0;
            end else begin

                if (RW == 0 && !FULL && SP != 3'd4) begin
                    stack_mem[SP] <= dataIn;
                    SP <= SP - 1;
                end

                if (RW == 1 && !EMPTY) begin
                    dataOut <= stack_mem[SP];
                    stack_mem[SP] <= 4'b0;
                    SP <= SP + 1;
                end

                EMPTY <= (SP == 3'd4);
                FULL <= (SP == 3'd0);
            end
        end
    end

endmodule

