module traffic_light(
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);
    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: begin
                    red <= 1;
                    if (cnt == 3) begin
                        state <= s3_green;
                        red <= 0;
                    end
                end
                s3_green: begin
                    green <= 1;
                    if (cnt == 3) begin
                        state <= s2_yellow;
                        green <= 0;
                    end
                end
                s2_yellow: begin
                    yellow <= 1;
                    if (cnt == 3) begin
                        state <= s1_red;
                        yellow <= 0;
                    end
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green) begin
                cnt <= 10;
            end else begin
                case (state)
                    s1_red: cnt <= 60;
                    s3_green: cnt <= 5;
                    s2_yellow: cnt <= 10;
                    default: cnt <= cnt - 1;
                endcase
            end
            clock <= cnt;
        end
    end


    always @(*) begin
        if (state == s3_green && cnt > 10 && pass_request) begin
            cnt <= 10;
        end else if (state == s3_green && cnt <= 10) begin
            cnt <= cnt;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red, p_yellow, p_green} <= 3'b0;
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end

endmodule

