module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] orig_dividend;
    reg [7:0] orig_divisor;
    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg div_sign_orig, div_sign;
    reg [16:0] SR;

    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] NEG_DIVISOR;
    wire [8:0] upper_sub;
    wire carry_out;

    assign upper_sub = SR[16:8] - NEG_DIVISOR;
    assign carry_out = ~upper_sub[8];

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            orig_dividend <= 0;
            orig_divisor <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            div_sign_orig <= 0;
            div_sign <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            NEG_DIVISOR <= 0;
            result <= 0;
        end else begin
            res_valid <= 0;

            if (opn_valid && !res_valid) begin
                orig_dividend <= dividend;
                orig_divisor <= divisor;

                if (sign) begin
                    div_sign_orig <= dividend[7];
                    div_sign <= divisor[7];
                    abs_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                    abs_divisor <= divisor[7] ? (~divisor + 1) : divisor;
                    NEG_DIVISOR <= -abs_divisor;
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    NEG_DIVISOR <= ~divisor + 1;
                end

                SR <= {abs_dividend, 8'b0} << 1;
                cnt <= 1;
                start_cnt <= 1;
            end

            if (start_cnt && cnt < 8) begin
                SR <= SR << 1;
                if (carry_out) begin
                    SR[16:8] <= upper_sub[7:0];
                    SR[0] <= 1'b1;
                end else begin
                    SR[0] <= 1'b0;
                end
                cnt <= cnt + 1;
            end else if (start_cnt && cnt == 8) begin
                start_cnt <= 0;
                cnt <= 0;

                reg [7:0] rem = SR[15:8];
                reg [7:0] quo = SR[7:0];

                if (sign) begin
                    if (div_sign_orig ^ div_sign) begin
                        quo = ~quo + 1;
                    end
                    if (div_sign_orig) begin
                        rem = ~rem + 1;
                    end
                end

                result <= {rem, quo};
                res_valid <= 1;
            end
        end
    end
endmodule

