module div_16bit(A, B, result, odd);
    input [15:0] A, B;
    output reg [15:0] result, odd;
    reg [15:0] a_reg, b_reg;

    always @(A, B) begin
        a_reg = A;
        b_reg = B;
    end

    always @(a_reg, b_reg) begin
        reg [7:0] rem;
        reg [15:0] div_quotient;
        integer i;

        rem = 8'b0;
        div_quotient = 16'b0;
        for (i = 15;
 i >= 0;
 i = i - 1) begin
            rem = (rem << 1) | ((a_reg >> i) & 8'h1);
            if (rem >= b_reg) begin
                rem = rem - b_reg;
                div_quotient[i] = 1'b1;
            end else begin
                div_quotient[i] = 1'b0;
            end
        end
        result = div_quotient;
        odd = {8'b0, rem};
    end
endmodule

