module comparator_4bit(A, B, A_greater, A_equal, A_less);
    input [3:0] A, B;
    output A_greater, A_equal, A_less;

    wire [4:0] temp;

    assign temp = {1'b0, A} + {1'b0, ~B} + 5'd1;

    assign A_less = ~temp[4];
