module adder_bcd (A, B, Cin, Sum, Cout);
    input [3:0] A, B;
    input Cin;
    output [3:0] Sum;
    output Cout;

    wire [4:0] sum_binary;
    wire correction_needed;
    wire [4:0] sum_corrected;

    assign sum_binary = A + B + Cin;
    assign correction_needed = (sum_binary > 5'd9);
    assign sum_corrected = correction_needed ? (sum_binary + 5'd6) : sum_binary;

    assign Sum = sum_corrected[3:0];
    assign Cout = correction_needed;

endmodule

