module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire [N-1:0] a_abs, b_abs;
    wire signed [N-1:0] a_signed = a;
    wire signed [N-1:0] b_signed = b;


    assign a_abs = a_sign ? (-a) : a;
    assign b_abs = b_sign ? (-b) : b;

    always @* begin
        if (a_sign == b_sign) begin

            res = a_abs + b_abs;
            res[N-1] = a_sign;
        end else begin

            if (a_signed > b_signed)
                res = a_signed - b_signed;
            else
                res = b_signed - a_signed;
        end
    end

    assign c = res;

endmodule

