module fixed_point_subtractor #(parameter Q=4, N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);
    wire a_gt_b = ($signed(a) > $signed(b)) ? 1'b1 : 1'b0;

    always @(*) begin
        res = a - b;
        if (res == 0)
            res[N-1] = 1'b0;
        else if (!same_sign) begin
            if (sign_a && !sign_b)
                res[N-1] = 1'b1;
            else
                res[N-1] = ~a_gt_b;
        end
        c = res;
    end
endmodule

