module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg [23:0] a_mantissa, b_mantissa, z_mantissa;
reg [9:0] a_exponent, b_exponent, z_exponent;
reg a_sign, b_sign, z_sign;
reg [47:0] product;
reg guard_bit, round_bit, sticky;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
    end else begin
        case (counter)
            0: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= {1'b1, a[22:0]};
                b_mantissa <= {1'b1, b[22:0]};


                if ((a_exponent == 9'hff && a_mantissa != 0) || 
                    (b_exponent == 9'hff && b_mantissa != 0)) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'h000001};
                    counter <= 0;
                end else if ((a_exponent == 9'hff && a_mantissa == 0) && 
                            (b_exponent == 9'hff && b_mantissa == 0)) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'h000001};
                    counter <= 0;
                end else if (a_exponent == 9'hff && a_mantissa == 0) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                    counter <= 0;
                end else if (b_exponent == 9'hff && b_mantissa == 0) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                    counter <= 0;
                end else if (a_mantissa == 0 && b_mantissa == 0) begin
                    z <= {a_sign ^ b_sign, 31'h0};
                    counter <= 0;
                end else begin
                    product <= a_mantissa * b_mantissa;
                    counter <= 1;
                end
            end
            1: begin

                z_exponent <= a_exponent + b_exponent - 9'd127;
                z_sign <= a_sign ^ b_sign;
                counter <= 2;
            end
            2: begin

                if (product[47:46] == 2'b10) begin
                    product <= product >> 1;
                    z_exponent <= z_exponent + 1;
                end
                guard_bit <= product[23];
                round_bit <= product[22];
                sticky <= |product[21:0];
                counter <= 3;
            end
            3: begin

                if (guard_bit) begin
                    if (round_bit | sticky | product[24]) begin
                        z_mantissa <= product[46:24] + 1;
                    end else begin
                        z_mantissa <= product[46:24];
                    end
                end else begin
                    z_mantissa <= product[46:24];
                end
                if (z_mantissa[23]) begin
                    z_mantissa <= z_mantissa >> 1;
                    z_exponent <= z_exponent + 1;
                end
                counter <= 4;
            end
            4: begin

                if (z_exponent > 9'hfe) begin
                    z <= {z_sign, 8'hff, 23'h0};
                end else if (z_exponent < 9'h01) begin
                    z <= {z_sign, 31'h0};
                end else begin
                    z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                end
                counter <= 0;
            end
            default: counter <= 0;
        endcase
    end
end

endmodule

