module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wrstn,
    input wire winc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    input wire rclk,
    input wire rrstn,
    input wire rinc,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);

    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram_inst (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(raddr_bin),
        .rdata(rdata)
    );


    reg [3:0] waddr_bin, raddr_bin;


    wire [3:0] wptr_gray = (waddr_bin >> 1) ^ waddr_bin;
    wire [3:0] rptr_gray = (raddr_bin >> 1) ^ raddr_bin;


    reg [3:0] rptr_gray_sync1, rptr_gray_sync;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync <= rptr_gray_sync1;
        end
    end


    reg [3:0] wptr_gray_sync1, wptr_gray_sync;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync <= wptr_gray_sync1;
        end
    end


    assign rempty = (rptr_gray == wptr_gray_sync);
    assign wfull = (wptr_gray[3] != rptr_gray_sync[3]) &&
                   (wptr_gray[2] != rptr_gray_sync[2]) &&
                   (wptr_gray[1] == rptr_gray_sync[1]) &&
                   (wptr_gray[0] == rptr_gray_sync[0]);


    wire wenc = winc && !wfull;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) waddr_bin <= 0;
        else if (wenc) waddr_bin <= waddr_bin + 1;
    end


    wire renc = rinc && !rempty;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) raddr_bin <= 0;
        else if (renc) raddr_bin <= raddr_bin + 1;
    end
endmodule


