module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;


always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin

            integer i;
            for (i = 0;
 i < 4;
 i = i + 1)
                stack_mem[i] <= 4'b0;
            SP <= 3'b100;
            dataOut <= 4'b0;
        end else begin
            reg [2:0] next_SP = SP;


            if (!FULL && !RW)
                next_SP = SP - 1;

            if (!EMPTY && RW)
                next_SP = SP + 1;



            if (!EMPTY && RW)
                dataOut <= stack_mem[SP];


            if (!FULL && !RW)
                stack_mem[SP - 1] <= dataIn;


            if (!EMPTY && RW)
                stack_mem[SP] <= 4'b0;


            SP <= next_SP;
            EMPTY <= (next_SP == 3'b100);
            FULL <= (next_SP == 3'b000);
        end
    end
end

endmodule

