module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

reg [7:0] data_lock;
reg stored;
reg [15:0] data_temp;
reg valid_temp;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_lock <= 8'b0;
        stored <= 1'b0;
        data_temp <= 16'b0;
        valid_temp <= 1'b0;
        data_out <= 16'b0;
        valid_out <= 1'b0;
    end else begin
        if (stored) begin
            if (valid_in) begin
                data_temp <= {data_lock, data_in};
                valid_temp <= 1'b1;
                stored <= 1'b0;
            end else begin
                valid_temp <= 1'b0;
            end
        end else begin
            if (valid_in) begin
                data_lock <= data_in;
                stored <= 1'b1;
            end
        end
        data_out <= data_temp;
        valid_out <= valid_temp;
    end
end

