module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] temp_dividend, temp_divisor;
    reg [7:0] absolute_dividend, absolute_divisor;
    reg [8:0] neg_divisor;
    reg [7:0] remainder_reg, quotient_reg;
    reg [3:0] counter;
    reg start_cnt;
    wire sign_quotient, sign_remainder;
    reg [7:0] final_quotient, final_remainder;

    assign sign_quotient = temp_dividend[7] ^ temp_divisor[7];
    assign sign_remainder = temp_dividend[7];

    always @(posedge clk) begin
        if (rst) begin
            temp_dividend <= 0;
            temp_divisor <= 0;
            absolute_dividend <= 0;
            absolute_divisor <= 0;
            neg_divisor <= 0;
            remainder_reg <= 0;
            quotient_reg <= 0;
            counter <= 0;
            start_cnt <= 0;
            res_valid <= 0;
            result <= 0;
            final_quotient <= 0;
            final_remainder <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                temp_dividend <= dividend;
                temp_divisor <= divisor;
                if (sign) begin
                    absolute_dividend <= dividend[7] ? (-dividend) : dividend;
                    absolute_divisor <= divisor[7] ? (-divisor) : divisor;
                end else begin
                    absolute_dividend <= dividend;
                    absolute_divisor <= divisor;
                end
                neg_divisor <= -absolute_divisor;
                remainder_reg <= 0;
                quotient_reg <= absolute_dividend << 1;
                counter <= 4'd1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                reg [8:0] sub_result;
                reg carry_out;
                reg quotient_bit;
                reg [7:0] new_remainder;

                sub_result = {1'b0, remainder_reg} - neg_divisor;
                carry_out = (sub_result[8] == 1'b0) ? 1'b1 : 1'b0;

                if (carry_out) begin
                    new_remainder = sub_result[7:0];
                    quotient_bit = 1'b1;
                end else begin
                    new_remainder = remainder_reg;
                    quotient_bit = 1'b0;
                end

                remainder_reg <= {remainder_reg[6:0], quotient_reg[7]};
                quotient_reg <= {quotient_reg[6:0], quotient_bit};

                if (counter == 4'd8) begin
                    start_cnt <= 0;
                    counter <= 0;
                    final_quotient = quotient_reg;
                    final_remainder = remainder_reg;

                    if (sign) begin
                        if (sign_quotient)
                            final_quotient = -final_quotient;
                        if (sign_remainder)
                            final_remainder = -final_remainder;
                    end

                    result <= {final_remainder, final_quotient};
                    res_valid <= 1;
                end else begin
                    counter <= counter + 1;
                end
            end
        end
    end
endmodule

