module div_16bit(
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result = 0,
    output reg [15:0] odd = 0
);
    reg [15:0] a_reg;
    reg [7:0] b_reg;


    always @(A or B) begin
        a_reg = A;
        b_reg = B;
    end


    always @(A or B) begin
        result = 0;
        odd = 0;


        reg [7:0] current_remainder = a_reg[15:8];
        reg [7:0] divisor = b_reg;
        reg [15:0] quotient = 0;

        for (int i = 0;
 i < 16;
 i = i + 1) begin

            if (current_remainder >= divisor) begin
                quotient[15 - i] = 1'b1;
                current_remainder = current_remainder - divisor;
            end else begin
                quotient[15 - i] = 1'b0;
            end


            current_remainder = {current_remainder[6:0], a_reg[15 - i]};
        end

        result = quotient;
        odd = {8'b0, current_remainder};
    end

endmodule

