module fixed_point_adder #(parameter Q = 2, N = 4) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;
    wire [N-1:0] sum;
    wire overflow;
    wire sign_res;

    always @* begin
        if (sign_a == sign_b) begin
            sum = a + b;
            overflow = (sum[N-1] ^ sign_a);
            if (overflow) begin
                res = sign_a ? {1'b1, {(N-1){1'b0}}} : {1'b0, {(N-1){1'b1}}};
            end else begin
                res = sum;
            end
        end else begin
            if (abs_a > abs_b) begin
                res = a - b;
                sign_res = 0;
            end else begin
                res = b - a;
                sign_res = 1;
            end
            res[N-1] = sign_res;
        end
        c = res;
    end

endmodule

