module fixed_point_subtractor #(parameter Q=2, N=4) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;

    always @* begin
        reg [N-1:0] sum;
        reg sign_positive;
        res = a - b;


        if (a[N-1] == b[N-1]) begin

            res[N-1] = a[N-1];
        end else begin

            if (a[N-1] == 0 && b[N-1] == 1) begin

                sum = a + (-b);
                sign_positive = (a > (-b)) ? 1'b1 : 1'b0;
            end else begin

                sum = a - b;
                sign_positive = (a < b) ? 1'b1 : 1'b0;
            end
            sum[N-1] = sign_positive;
            res = sum;
        end


        if (res == {N{1'b0}}) begin
            res[N-1] = 1'b0;
        end
    end

    assign c = res;

endmodule

