    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] product_mantissa_a, product_mantissa_b;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [7:0] stored_exponent;
    reg [22:0] rounded_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case(counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    z_sign <= 1'b0;
                    stored_exponent <= 8'b0;


                    if ((a_exponent == 8'hff && a_mantissa != 0) || 
                        (b_exponent == 8'hff && b_mantissa != 0) ||
                        (a_exponent == 8'hff && b_exponent == 8'hff) ||
                        ((a_exponent == 8'hff || b_exponent == 8'hff) && 
                         (a_mantissa == 0 || b_mantissa == 0))) begin

                        if ((a_exponent == 8'hff && a_mantissa != 0) || 
                            (b_exponent == 8'hff && b_mantissa != 0)) begin

                            z <= {a_sign ^ b_sign, 8'hff, 23'h000001};
                        end else if ((a_exponent == 8'hff && b_exponent == 0 && b_mantissa == 0) ||
                                   (b_exponent == 8'hff && a_exponent == 0 && a_mantissa == 0)) begin

                            z <= {a_sign ^ b_sign, 8'hff, 23'h000001};
                        end else begin

                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end
                        counter <= 3'b001;
                    end else begin

                        z_sign <= a_sign ^ b_sign;

                        stored_exponent <= a_exponent + b_exponent - 8'd127;

                        product_mantissa_a <= (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                        product_mantissa_b <= (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                        product <= product_mantissa_a * product_mantissa_b;
                        counter <= 3'b001;
                    end
                end

                3'b001: begin

                    if (product[47]) begin

                        product <= {1'b0, product[47:1]};
                        stored_exponent <= stored_exponent + 9'd1;
                        guard_bit <= product[0];
                        round_bit <= 0;
                        sticky <= 0;
                    end else begin
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end
                    counter <= 3'b010;
                end

                3'b010: begin

                    rounded_mantissa <= product[46:24];


                    if (guard_bit && (round_bit | sticky)) begin
                        rounded_mantissa <= rounded_mantissa + 1;
                    end
                    counter <= 3'b011;
                end

                3'b011: begin

                    if (rounded_mantissa[23]) begin

                        stored_exponent <= stored_exponent + 9'd1;
                        rounded_mantissa <= rounded_mantissa >> 1;
                    end

                    if (stored_exponent >= 9'd255) begin

                        z <= {z_sign, 8'hff, 23'h0};
                    end else begin

                        z <= {z_sign, stored_exponent[7:0], rounded_mantissa[22:0]};
                    end
                    counter <= 3'b000;
                end

                default: counter <= 3'b000;
            endcase
        end
    end
