    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    output wire rempty,
    input wire wrstn,
    input wire rclk,
    input wire rinc,
    output wire [WIDTH-1:0] rdata,
    input wire rrstn
);
    localparam ADDR_WIDTH = $clog2(DEPTH);
