    reg [ADDR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync;
    wire [ADDR_WIDTH-1:0] wptr_gray_next;

    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc_enabled),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc_enabled),
        .raddr(raddr_bin),
        .rdata(rdata)
    );

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            waddr_bin <= 0;
        else if (winc_enabled)
            waddr_bin <= waddr_bin + 1;
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            raddr_bin <= 0;
        else if (rinc_enabled)
            raddr_bin <= raddr_bin + 1;
