    end

    assign wptr_gray_next = binary_to_gray(waddr_bin + 1);
    assign wfull = (wptr_gray_next == rptr_gray_sync);
    assign rempty = (rptr_gray == wptr_gray_sync);

    assign winc_enabled = winc && !wfull;
    assign rinc_enabled = rinc && !rempty;
