    if (rst) begin
        res_valid <= 0;
        result <= 0;
        cnt <= 0;
        start_cnt <= 0;
        SR <= 0;
        stored_dividend_abs <= 0;
        stored_divisor_abs <= 0;
        sign_dividend <= 0;
        sign_divisor <= 0;
        NEG_DIVISOR <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            sign_dividend <= sign && dividend[7];
            sign_divisor <= sign && divisor[7];
            stored_dividend_abs <= sign ? (~dividend + 1) : dividend;
            stored_divisor_abs <= sign ? (~divisor + 1) : divisor;
            NEG_DIVISOR <= sign ? (- (sign ? (~divisor + 1) : divisor)) : (-divisor);

