                if (carry_out) begin
                    SR[15:8] <= sum[7:0];
                    SR[7:0] <= {SR[6:0], 1'b1};
                end else begin
                    SR[15:8] <= remainder_shifted[7:0];
                    SR[7:0] <= {SR[6:0], 1'b0};
                end
            end
        end

        if (res_valid && (opn_valid || rst)) begin
            res_valid <= 0;
        end
    end
