        reg [15:0] quotient;
        reg [15:0] remainder;
        quotient = 16'b0;
        remainder = {8'b0, a_reg[15:8]};


        for (i = 0;
 i < 16;
 i = i + 1) begin
            if (remainder >= {8'b0, b_reg}) begin
                quotient[i] = 1'b1;
                remainder = remainder - {8'b0, b_reg};
            end else begin
                quotient[i] = 1'b0;
            end

            remainder = {remainder[14:0], a_reg[15 - i]};
        end

        result = quotient;

        odd = {8'b0, remainder[7:0]};
    end

