module fixed_point_adder #(parameter Q=3, parameter N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;
    wire [N-1:0] sum_abs = abs_a + abs_b;
    wire [N-1:0] abs_diff;

    always @(*) begin
        if (sign_a == sign_b) begin

            res = {sign_a, sum_abs[N-1:0]};
        end else begin

            if ($signed(abs_a) >= $signed(abs_b)) begin
                abs_diff = abs_a - abs_b;
                res = {sign_a, abs_diff};
            end else begin
                abs_diff = abs_b - abs_a;
                res = {sign_b, abs_diff};
            end
        end
    end

    assign c = res;

endmodule

