module fixed_point_subtractor #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c = 0
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];


    wire [N-2:0] mag_a = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
    wire [N-2:0] mag_b = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];

    wire same_sign = (sign_a == sign_b);
    reg [N-1:0] c_reg;

    always @* begin
        if (same_sign) begin

            reg [N-2:0] mag_diff = mag_a - mag_b;
            reg sign_diff = sign_a;


            if (mag_a < mag_b) begin
                mag_diff = mag_b - mag_a;
            end

            c_reg = {sign_diff, mag_diff};
        end else begin

            if (mag_a > mag_b) begin
                c_reg = {~sign_a, mag_a - mag_b};
            end else if (mag_a < mag_b) begin
                c_reg = {~sign_b, mag_b - mag_a};
            end else begin

                c_reg = {1'b0, {(N-1){1'b0}}};
            end
        end


        if (c_reg == 0)
            c_reg = {1'b0, {(N-1){1'b0}}};
    end

    assign res = c_reg;
    assign c = res;
endmodule

