module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    reg current_state;
    localparam IDLE = 1'b0;
    localparam UP = 1'b1;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            current_state <= IDLE;
            data_out <= 1'b0;
        end else begin
            case (current_state)
                IDLE: begin
                    if (data_in) begin
                        current_state <= UP;
                        data_out <= 1'b0;
                    end else begin
                        current_state <= IDLE;
                        data_out <= 1'b0;
                    end
                end
                UP: begin
                    if (!data_in) begin
                        current_state <= IDLE;
                        data_out <= 1'b1;
                    end else begin
                        current_state <= IDLE;
                        data_out <= 1'b0;
                    end
                end
            endcase
        end
    end
