                reg [3:0] cnt;
                reg start_cnt;
                reg saved_sign;
                reg [7:0] saved_dividend_sign, saved_divisor_sign;
                reg res_valid_reg;

                always @(posedge clk) begin
                    if (rst) begin
                        res_valid_reg <= 0;
                        start_cnt <= 0;
                        cnt <= 0;
                        SR <= 0;
                        quotient_reg <= 0;
                        remainder_reg <= 0;
                        saved_sign <= 0;
                        saved_dividend_sign <= 0;
                        saved_divisor_sign <= 0;
                        result <= 0;
                    end else begin
                        if (opn_valid && !res_valid_reg) begin

                            saved_sign <= sign;

                            if (sign && dividend[7]) begin
                                abs_dividend <= -dividend;
                            end else begin
                                abs_dividend <= dividend;
                            end
                            if (sign && divisor[7]) begin
                                abs_divisor <= -divisor;
                            end else begin
                                abs_divisor <= divisor;
                            end

                            saved_dividend_sign <= dividend[7];
                            saved_divisor_sign <= divisor[7];

                            SR <= {abs_dividend, 8'b0} << 1;

                            start_cnt <= 1;
                            cnt <= 1;
                        end else if (start_cnt) begin
                            if (cnt <= 8) begin





                                reg [8:0] temp_remainder;
                                reg carry_out;
                                temp_remainder = SR[15:7] - {1'b0, abs_divisor};
                                carry_out = ~temp_remainder[8];



                                SR <= (SR << 1);
                                SR[0] <= carry_out;


                                cnt <= cnt + 1;
                            end else begin

                                start_cnt <= 0;
                                res_valid_reg <= 1;

                                if (saved_sign) begin
                                    quotient_reg <= (saved_dividend_sign ^ saved_divisor_sign) ? -SR[7:0] : SR[7:0];
                                    remainder_reg <= (saved_dividend_sign) ? -SR[15:8] : SR[15:8];
                                end else begin
                                    quotient_reg <= SR[7:0];
                                    remainder_reg <= SR[15:8];
                                end
                                result <= {remainder_reg, quotient_reg};
                            end
                        end
                    end
                end

                always @(posedge clk) begin
                    if (rst) begin
                        res_valid <= 0;
                    end else begin
                        res_valid <= res_valid_reg;
                    end
                end

