module div_16bit(A, B, result, odd);
    input [15:0] A, B;
    output reg [15:0] result, odd;

    reg [15:0] a_reg, b_reg;


    always @(A, B) begin
        a_reg = A;

        b_reg = B;
    end


    always @(*) begin
        reg [15:0] dividend = a_reg;
        reg [7:0] divisor = b_reg;
        reg [15:0] quotient = 0;
        reg [7:0] remainder = 0;

        for (int i = 15;
 i >= 0;
 i = i - 1) begin
            remainder = {remainder[6:0], dividend[i]};

            if (remainder >= divisor) begin
                quotient[i] = 1;
                remainder = remainder - divisor;
            end else begin
                quotient[i] = 0;
            end
        end

        result = quotient;
        odd = {8'b0, remainder};

    end
endmodule

