module fixed_point_adder #(parameter Q = 2, N = 8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    reg [N-1:0] a_abs, b_abs;
    reg a_abs_gt_b_abs;
    reg [N-1:0] sum;

    always @(*) begin

        a_abs = a_sign ? (~a + 1) : a;
        b_abs = b_sign ? (~b + 1) : b;


        a_abs_gt_b_abs = (a_abs > b_abs);
    end

    always @(*) begin
        if (a_sign == b_sign) begin

            sum = a + b;
            res = sum;


            if ((a_sign == 0 && sum[N-1] == 1) || (a_sign == 1 && sum[N-1] == 0)) begin

                if (a_sign == 0) begin

                    res = {1'b0, {(N-2){1'b1}}};
                end else begin

                    res = {1'b1, {(N-1){1'b0}}};
                end
            end
        end else begin

            if (a_abs_gt_b_abs) begin
                res = a_abs - b_abs;
            end else begin
                res = b_abs - a_abs;
            end


            res[N-1] = a_abs_gt_b_abs ? a_sign : 1'b0;
        end


        c = res;
    end

endmodule

