module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa, z_mantissa;
    reg [48:0] product;
    reg guard_bit, round_bit, sticky;
    reg [47:0] product_shifted;
    reg [9:0] exp_sum;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                    if ((a[30:23] == 8'hFF && (a[22:0] != 0)) || (b[30:23] == 8'hFF && (b[22:0] != 0))) begin

                        z <= 32'h7FC00000;
                        counter <= 3'b001;
                    end else if ((a[30:23] == 8'hFF) || (b[30:23] == 8'hFF)) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 8'hFF;
                        z_mantissa <= 23'b0;
                        z <= {z_sign, z_exponent, z_mantissa};
                        counter <= 3'b001;
                    end else if ((a[30:23] == 0 && a[22:0] == 0) || (b[30:23] == 0 && b[22:0] == 0)) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 0;
                        z_mantissa <= 0;
                        z <= {z_sign, z_exponent, z_mantissa};
                        counter <= 3'b001;
                    end else begin
                        exp_sum <= a_exponent + b_exponent - 127;
                        counter <= 3'b001;
                    end
                end

                3'b001: begin
                    product <= a_mantissa * b_mantissa;
                    counter <= 3'b010;
                end

                3'b010: begin

                    if (product[47]) begin
                        product_shifted <= product >> 1;
                        exp_sum <= exp_sum + 1;
                        {guard_bit, round_bit, sticky} <= {product_shifted[23], product_shifted[22], |product_shifted[21:0]};
                        z_mantissa <= product_shifted[46:24];
                    end else begin
                        product_shifted <= product;
                        {guard_bit, round_bit, sticky} <= {product[24], product[23], |product[22:0]};
                        z_mantissa <= product[47:25];
                    end
                    counter <= 3'b011;
                end

                3'b011: begin

                    if (guard_bit && (round_bit || sticky)) begin
                        if (z_mantissa == 23'h7FFFFF) begin
                            z_exponent <= exp_sum + 1;
                            z_mantissa <= 23'b0;
                        end else begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end
                    counter <= 3'b100;
                end

                3'b100: begin

                    if (z_exponent >= 255) begin

                        z_exponent <= 8'hFF;
                        z_mantissa <= 0;
                    end else if (z_exponent == 0) begin

                        z_exponent <= 0;

                    end
                    z <= {a_sign ^ b_sign, z_exponent, z_mantissa};
                    counter <= 3'b000;
                end
            endcase
        end
    end
endmodule

